export type Scenario = {
  id: string; title: string; description: string; expectedRootCause: string; learningObjectives: string[];
  evidence: {action: string; output: string; interpretation: string}[]; mitigation: string; prevention: string;
  runbook: {containment: string; commands: {label: string; command: string; why: string}[]; escalation: string};
  category: string;
};

const kubectlPodCommands = [
  {label: 'Object and events', command: 'kubectl describe pod <pod> -n <namespace>', why: 'Read the scheduler, lifecycle, probe, and termination evidence before changing the workload.'},
  {label: 'Previous container output', command: 'kubectl logs <pod> -n <namespace> -c <container> --previous', why: 'A restarted container may have lost its only useful application-level error.'},
  {label: 'Scoped live state', command: 'kubectl get pod <pod> -n <namespace> -o yaml', why: 'Compare intended spec, status, resource limits, node placement, and recent conditions.'},
];
const gpuCommands = [
  {label: 'GPU inventory', command: 'kubectl describe node <node> | sed -n \'/Allocatable:/,/System Info:/p\'', why: 'Confirm the resource the scheduler actually sees; do not infer it from a dashboard.'},
  {label: 'Driver and hardware evidence', command: 'sudo dmesg -T | grep -Ei \'NVRM|Xid\' && nvidia-smi -q', why: 'Correlate host driver/hardware events with the affected GPU UUID.'},
  {label: 'Operator operands', command: 'kubectl get pods -n gpu-operator -o wide && kubectl logs -n gpu-operator -l app=nvidia-device-plugin --tail=200', why: 'Separate a device-plugin/driver failure from a workload scheduling issue.'},
];
const fabricCommands = [
  {label: 'NCCL signal', command: 'NCCL_DEBUG=INFO NCCL_DEBUG_SUBSYS=NET,INIT <launch-command>', why: 'Capture interface and peer-selection evidence before changing NCCL knobs.'},
  {label: 'Link and topology', command: 'ibstatus; ibstat; nvidia-smi topo -m', why: 'Verify active ports, expected rate/layer, and GPU-to-NIC locality.'},
  {label: 'RoCE counters', command: 'ethtool -S <nic> | grep -Ei \'drop|err|pause|pfc|ecn\'', why: 'Rising drops, pause, PFC, or ECN signals point to fabric configuration or congestion, not an application bug.'},
];
const nodeCommands = [
  {label: 'Node conditions', command: 'kubectl describe node <node>', why: 'Check Ready, MemoryPressure, DiskPressure, PIDPressure, taints, and recent events.'},
  {label: 'Runtime filesystem', command: 'sudo df -h /var/lib/containerd; sudo df -i /var/lib/containerd', why: 'Check both bytes and inodes before reclaiming images or restarting kubelet.'},
  {label: 'Kubelet evidence', command: 'sudo journalctl -u kubelet --since \'30 min ago\' --no-pager', why: 'Find the mechanism behind a NotReady transition, rather than treating it as a generic node failure.'},
];
const linuxCommands = [
  {label: 'Pressure overview', command: 'uptime; vmstat 1 5; cat /proc/pressure/{cpu,memory,io}', why: 'Separate runnable CPU pressure, blocked I/O, reclaim, and sustained stall time.'},
  {label: 'Process evidence', command: 'ps -eo pid,ppid,stat,wchan:32,pcpu,pmem,comm --sort=-pcpu | head -30', why: 'Find runnable, D-state, zombie, memory-heavy, or blocked processes and the kernel wait point.'},
  {label: 'Per-process behavior', command: 'sudo pidstat -durw 1 5; sudo lsof -p <pid> | head', why: 'Correlate CPU, I/O, faults, context switches, and open resources with the affected service.'},
];
const controlPlaneCommands = [
  {label: 'API readiness', command: 'kubectl get --raw=/readyz?verbose', why: 'Identify the unhealthy API-server dependency without relying on a generic health dashboard.'},
  {label: 'Request pressure', command: 'kubectl get --raw=/metrics | grep -E \'apiserver_request_duration|apiserver_current_inflight\'', why: 'Check latency and concurrency by verb/resource before blaming etcd.'},
  {label: 'etcd signal', command: 'etcdctl endpoint status --cluster -w table; etcdctl endpoint health --cluster', why: 'Inspect leader, revision, database size, raft index, and endpoint health with quorum awareness.'},
];
const automationCommands = [
  {label: 'Execution record', command: 'python -m your_tool --dry-run --log-format=json', why: 'Preserve inputs, planned actions, correlation ID, and dry-run output before allowing mutation.'},
  {label: 'Retry and deadline metrics', command: 'sum by (operation,status) (rate(automation_attempts_total[5m]))', why: 'Distinguish useful retry from amplification and permanent-error loops.'},
  {label: 'Idempotency audit', command: 'pytest -q tests/test_idempotency.py tests/test_partial_failure.py', why: 'Reproduce repeated execution and mid-flight failure before rerunning against production.'},
];
const observabilityCommands = [
  {label: 'Target health', command: 'up{job=~".*gpu.*|.*dcgm.*"}', why: 'Separate missing telemetry from a healthy zero-valued metric.'},
  {label: 'Cardinality', command: 'topk(20, count by (__name__)({__name__=~".+"}))', why: 'Find unexpectedly expensive metric families before changing Prometheus resources.'},
  {label: 'Pipeline evidence', command: 'kubectl logs -n monitoring <collector-or-exporter-pod> --since=30m', why: 'Trace scrape/export/remote-write failures through the telemetry path.'},
];
const slurmCommands = [
  {label: 'Queue reason', command: 'squeue -j <jobid> -o "%.18i %.9P %.8j %.8T %.10M %.6D %R"', why: 'The pending reason is the first scheduling branch, not an error to bypass.'},
  {label: 'Job request', command: 'scontrol show job <jobid>', why: 'Inspect requested GRES/TRES, constraints, partition, reservation, priority, and dependency.'},
  {label: 'Capacity and state', command: 'sinfo -Nel; scontrol show node <node>', why: 'Compare request with allocatable GPU type/topology and drained/down node reasons.'},
];
const bmcCommands = [
  {label: 'BMC reachability', command: 'ping -c3 <bmc-ip>; ipmitool -I lanplus -H <bmc-ip> -U admin -P *** chassis status', why: 'Confirm whether the BMC network path itself is down before assuming the firmware update is merely slow.'},
  {label: 'Redfish task/update state', command: 'curl -sk -u admin:*** https://<bmc-ip>/redfish/v1/TaskService/Tasks | jq .', why: 'A stuck update usually still has a Task resource reporting percent-complete or an error state even when new Redfish requests stop responding.'},
  {label: 'Out-of-band console', command: 'ipmitool -I lanplus -H <bmc-ip> -U admin -P *** sol activate', why: 'Serial-over-LAN can reveal a POST hang or a wedged BMC even when the Redfish HTTPS listener itself is unresponsive.'},
];
const pxeCommands = [
  {label: 'DHCP/TFTP capture', command: 'tcpdump -i eth0 port 67 or port 68 or port 69', why: 'Pinpoint the exact stage: no DHCPDISCOVER, offer but no TFTP fetch, or fetch but boot-mode mismatch.'},
  {label: 'DHCP scope and MAC registration', command: 'grep -i <mac> /etc/dhcp/dhcpd.conf; grep <mac> provisioning-system-inventory.csv', why: 'A mainboard RMA changes the MAC address; most provisioning systems require MAC pre-registration before offering PXE options.'},
  {label: 'Boot-mode and bootfile match', command: 'diff pxelinux.cfg/<old-mac> grub.cfg; ipmitool chassis bootparam get 5', why: 'Confirm the DHCP-handed bootfile-name matches the NIC firmware mode (legacy BIOS vs UEFI/HTTPBoot), which BIOS defaults can silently flip after an RMA.'},
];
const bcmCommands = [
  {label: 'Category-rendered state', command: 'cmsh -c "category use gpu-a100; show"', why: 'Confirm what the category says every member node should be running before comparing it to what one node actually has.'},
  {label: 'Node-level override diff', command: 'cmsh -c "device use gpu-node-09; show"; diff category-rendered-config node-actual-config', why: 'A hand-edit made outside the category shows up as a per-node override the category push cannot see or correct.'},
  {label: 'Provision/health history', command: 'cmsh -c "device use gpu-node-09; grabimage -w"', why: 'Determine whether the node has been reprovisioned since the manual edit, which decides if the drift is transient or has become permanent.'},
];
const ansibleCommands = [
  {label: 'Check/diff against target', command: 'ansible-playbook site.yml --limit gpu_nodes --check --diff', why: 'See the exact byte-level diff driving the changed= count before trusting or dismissing it.'},
  {label: 'Idempotency re-verification', command: 'ansible-playbook site.yml --limit <node> --check --diff   # run 3x consecutively', why: 'True idempotency is zero diff on a third consecutive run against an untouched node, not merely a successful exit code.'},
  {label: 'Source-data ordering audit', command: 'ansible <node> -m debug -a "var=dcgm_metrics_dict"', why: 'Confirm whether the underlying dict/merge order, not the rendered values, is what is unstable across runs.'},
];
const terraformCommands = [
  {label: 'Plan with replace markers isolated', command: 'terraform plan -out=tfplan; terraform show -json tfplan | jq \'.resource_changes[] | select(.change.actions|length>1)\'', why: 'Isolate every -/+ destroy-and-recreate action before scrolling past the plan summary line.'},
  {label: 'State vs real-infra refresh', command: 'terraform state show <resource>; terraform plan -refresh-only', why: 'Determine whether the divergence is state believing something reality no longer matches, rather than a real declared-config change.'},
  {label: 'Manual-change correlation', command: 'git log -p -- <resource>.tf; cloud console/audit-log history for <resource-id>', why: 'Correlate an out-of-band manual change with the moment state stopped matching reality.'},
];
const mpiCommands = [
  {label: 'Rank launch confirmation', command: 'srun --overlap --jobid=<id> ps aux | grep python', why: 'Confirm every expected rank process actually started before suspecting the NCCL/fabric layer at all.'},
  {label: 'MPI/PMIx bootstrap evidence', command: 'mpirun --report-bindings -np 8 ...; export PMIX_MCA_ptl_base_verbose=5', why: 'Missing or incomplete bindings output for one node means PMIx never heard back from it — an MPI/launch problem, not NCCL.'},
  {label: 'NCCL handoff point', command: 'NCCL_DEBUG=INFO NCCL_DEBUG_SUBSYS=INIT,NET <launch-command>', why: 'If MPI bootstrap completed for every rank and the hang begins at init_process_group, the problem has moved into NCCL/fabric territory.'},
];
const enrootCommands = [
  {label: 'Host-level GPU baseline', command: 'nvidia-smi -L', why: 'Confirm the driver/host GPU path is healthy before suspecting the container runtime at all.'},
  {label: 'Enroot NVIDIA hook presence', command: 'ls -l /etc/enroot/hooks.d/*nvidia*', why: 'Enroot only bind-mounts driver libraries/devices into the rootless filesystem if this hook file is present and enabled.'},
  {label: 'Container-side visibility env', command: 'srun --container-image=... --container-remap-root env | grep NVIDIA_VISIBLE_DEVICES', why: 'An empty or unset NVIDIA_VISIBLE_DEVICES inside the container is the tell that the hook never fired.'},
];
const selinuxCommands = [
  {label: 'Denial record', command: 'ausearch -m avc -ts recent', why: 'Find the exact denied syscall/path before assuming the monitoring agent itself is broken.'},
  {label: 'Human-readable explanation', command: 'audit2why < denial.log', why: 'Translate the raw AVC denial into which type/context mismatch is actually blocking access.'},
  {label: 'Mode and policy scope', command: 'sestatus; semanage fcontext -l | grep nvidia', why: 'Confirm enforcing mode and whether a GPU/monitoring-specific policy module or context mapping is missing entirely from the targeted policy.'},
];
const changeMgmtCommands = [
  {label: 'Compatibility matrix audit', command: 'diff canary_inventory.csv fleet_inventory.csv   # NIC model, firmware rev, GPU SKU', why: 'A canary that passes validates only the hardware/firmware variants it actually contains, nothing else in the fleet.'},
  {label: 'Canary validation gate results', command: 'dcgm-diag -r 3; nccl-tests all_reduce_perf   # canary set only', why: 'Bandwidth within baseline on the canary says nothing about a variant the canary never included.'},
  {label: 'Fleet stratification check', command: 'awk -F, \'{print $3}\' fleet_inventory.csv | sort | uniq -c', why: 'Quantify what fraction of the fleet the canary failed to represent before authorizing the next wave.'},
];
const dkmsCommands = [
  {label: 'Driver load failure signature', command: 'dmesg | grep -i nvidia; nvidia-smi', why: 'Confirm the failure is a DKMS/NVML driver-library version mismatch, not a hardware fault.'},
  {label: 'DKMS build status', command: 'dkms status', why: 'Determine whether the nvidia module built for the new kernel at all, or is still registered only against the previous kernel.'},
  {label: 'Patch pipeline sequencing', command: 'grep -i kernel /var/log/patch-pipeline.log', why: 'Confirm whether the kernel package update and DKMS rebuild were ever gated as one atomic step before the reboot.'},
];
const cicdCommands = [
  {label: 'Policy-check gate result', command: 'conftest test tfplan.json -p policy/', why: 'Confirm whether the destructive plan was actually blocked by policy, or whether it was bypassed.'},
  {label: 'Override-path audit trail', command: 'grep -i override pipeline_audit.log; git log --grep=\'emergency-override\'', why: 'An override that bypassed policy check should still leave an audit trail; its absence is itself the finding.'},
  {label: 'Post-hoc plan reconciliation', command: 'terraform plan -refresh-only', why: 'Determine what was actually applied versus what the bypassed policy check would have flagged, now that it is too late to block it.'},
];
const serviceCommands = [
  {label: 'User-visible SLI', command: 'curl -sS -o /dev/null -w "code=%{http_code} connect=%{time_connect} ttfb=%{time_starttransfer} total=%{time_total}\n" https://<service>/<path>', why: 'Confirm the symptom and split connection, server wait, and total latency before selecting a layer.'},
  {label: 'Golden signals by route', command: 'sum by (service,route,status) (rate(http_requests_total[5m])); histogram_quantile(0.99, sum by (le,service,route) (rate(http_request_duration_seconds_bucket[5m])))', why: 'Scope traffic, errors and latency without hiding a single failing route behind fleet averages.'},
  {label: 'Correlated application evidence', command: 'kubectl logs deploy/<service> -n <namespace> --since=30m | grep <correlation-id>', why: 'Trace one failed request across retries and dependencies instead of searching unbounded logs.'},
];
const databaseCommands = [
  {label: 'Pool saturation', command: 'sum(database_pool_active) / sum(database_pool_max); sum(rate(database_pool_timeouts_total[5m]))', why: 'Separate application-side pool exhaustion from database CPU or storage pressure.'},
  {label: 'Database sessions and waits', command: 'psql -c "select state,wait_event_type,wait_event,count(*) from pg_stat_activity group by 1,2,3 order by 4 desc;"', why: 'Identify idle-in-transaction, lock, I/O, client and connection pressure using server-side evidence.'},
  {label: 'Slow/blocked work', command: 'psql -c "select pid,now()-query_start as age,state,wait_event,left(query,120) from pg_stat_activity where state <> \'idle\' order by age desc;"', why: 'Find the work retaining connections or blocking progress before increasing pool size.'},
];
const edgeNetworkCommands = [
  {label: 'DNS and connection path', command: 'dig +trace <name>; curl -vk --resolve <name>:443:<ip> https://<name>/<path>', why: 'Separate name resolution from TCP/TLS/application behavior and test a specific backend path.'},
  {label: 'Socket/NAT pressure', command: 'ss -s; ss -tan state time-wait | wc -l; conntrack -S', why: 'Check ephemeral-port, TIME_WAIT and conntrack pressure before blaming the remote service.'},
  {label: 'Load-balancer/backend evidence', command: 'cloud-lb-health describe <backend>; query access logs by backend_status and upstream_connect_time', why: 'Distinguish client, load balancer and upstream response/connection failures.'},
];
const deliveryCommands = [
  {label: 'Release and change correlation', command: 'git log -1 --format=%H; kubectl rollout history deploy/<service> -n <namespace>', why: 'Tie impact to exact source, image, configuration and rollout revision.'},
  {label: 'Pipeline capacity', command: 'query runner_queue_seconds, runner_busy, job_duration, cache_hit by runner_pool and project', why: 'Separate slow jobs from a saturated or unfair shared runner fleet.'},
  {label: 'Rollback safety', command: 'compare application version, schema version, migration history and backward-compatibility contract', why: 'A binary rollback is unsafe when the database or event contract has already moved forward.'},
];
const streamingCommands = [
  {label: 'Consumer-group state', command: 'kafka-consumer-groups.sh --bootstrap-server <brokers> --describe --group <group>', why: 'Inspect lag per partition, consumer assignment and current/end offsets rather than one total lag number.'},
  {label: 'Partition distribution', command: 'kafka-topics.sh --bootstrap-server <brokers> --describe --topic <topic>', why: 'Confirm leader/replica health and whether the load is skewed onto a hot partition.'},
  {label: 'Consumer processing evidence', command: 'query records_consumed_rate, processing_seconds, rebalance_total, commit_latency by consumer and partition', why: 'Separate slow processing, rebalance churn and broker delivery issues.'},
];
const cacheCommands = [
  {label: 'Cache health', command: 'redis-cli INFO stats; redis-cli INFO memory', why: 'Measure hit/miss, evictions, memory and connection behavior before scaling application replicas.'},
  {label: 'Hot-key evidence', command: 'redis-cli --hotkeys; redis-cli --bigkeys', why: 'Find a skewed key or oversized value that fleet-average CPU and memory can hide.'},
  {label: 'Origin amplification', command: 'compare cache_misses_total with origin_requests_total and origin_latency during the incident window', why: 'Prove whether synchronized misses are overwhelming the source of truth.'},
];

const lustreCommands = [
  {label: 'OST/MDT capacity and bandwidth', command: 'lfs df -h; lfs df -i', why: 'Confirm whether the bottleneck is OST byte/inode capacity at all before assuming it is metadata-bound.'},
  {label: 'MDS metadata operation rate', command: 'lctl get_param mdt.*.md_stats', why: 'Directly measure open/create/unlink/getattr RPC rates on the metadata target, which OST bandwidth graphs never show.'},
  {label: 'Client-side RPC and export queue depth', command: 'lctl get_param mdc.*.stats; lctl get_param mdt.*.exports | grep -A2 nodeid', why: 'Confirm client requests are queuing on the metadata service rather than being served, and identify which clients are driving the load.'},
];
const gpfsCommands = [
  {label: 'Cluster and node state', command: 'mmgetstate -a', why: 'Confirm whether the cluster is active, arbitrating, or down on each node before assuming a single-node issue.'},
  {label: 'File system manager election', command: 'mmlsmgr', why: 'An unresolved manager election is the direct symptom of lost quorum, not a per-node fault.'},
  {label: 'Quorum and network diagnostics', command: 'mmdiag --network; mmlscluster', why: 'Confirm the configured quorum node count and which nodes are currently reachable, to check the surviving set against the majority threshold.'},
];
const xfsCommands = [
  {label: 'Bytes vs inode utilization', command: 'df -h /mnt/scratch; df -i /mnt/scratch', why: 'ENOSPC on create with low byte utilization is the signature of inode exhaustion, not a capacity problem.'},
  {label: 'XFS inode allocation detail', command: 'xfs_db -c "sb 0" -c "print icount ifree" -r <device>; xfs_info <mountpoint>', why: 'Confirm allocated versus free inode counts and the filesystem\'s inode size/imaxpct configuration set at format time.'},
  {label: 'File-count hot spot', command: 'find <mountpoint> -xdev -type f | cut -d/ -f1-4 | sort | uniq -c | sort -rn | head', why: 'Identify which directory tree is generating the disproportionate file count before deleting anything.'},
];
const grafanaCommands = [
  {label: 'Panel query freshness', command: 'curl -s "http://prometheus:9090/api/v1/query?query=timestamp(up)-time()"', why: 'Directly measure how stale the underlying sample is instead of trusting a rendered panel value.'},
  {label: 'Target scrape state', command: 'curl -s http://prometheus:9090/api/v1/targets | jq \'.data.activeTargets[] | {job:.labels.job, health:.health, lastScrape:.lastScrape}\'', why: 'A target in state down with an old lastScrape timestamp is an active outage even if a dashboard still renders a plausible-looking value.'},
  {label: 'Grafana datasource health', command: 'curl -s -u admin:*** http://grafana:3000/api/datasources/proxy/1/api/v1/query?query=up', why: 'Confirm Grafana itself can reach and query Prometheus, ruling out a Grafana-side rendering/caching issue versus a genuine scrape gap.'},
];
const lokiCommands = [
  {label: 'Label cardinality analysis', command: 'logcli series --analyze-labels \'{job="gpu-training"}\'', why: 'Identify which label is producing an unbounded number of distinct values before Loki\'s index absorbs any more of them.'},
  {label: 'Ingester stream pressure', command: 'curl -s http://loki:3100/metrics | grep -E \'loki_ingester_memory_streams|loki_ingester_streams_created_total\'', why: 'Confirm active stream count is the mechanism behind ingester memory growth, not raw log byte volume.'},
  {label: 'Query-side cost check', command: 'logcli query --limit=5 --stats \'{job="gpu-training"}\'', why: 'Confirm whether queries are scanning an excessive number of streams/chunks per request, the query-latency symptom of the same cardinality problem.'},
];
const networkOperatorCommands = [
  {label: 'Operator and operand state', command: 'kubectl get pods -n nvidia-network-operator -o wide; kubectl get nicclusterpolicy -o yaml', why: 'Compare the operator\'s declared firmware/driver baseline against which operand pods are actually failing.'},
  {label: 'Driver/firmware mismatch evidence', command: 'kubectl logs -n nvidia-network-operator -l app=mofed-driver --tail=200', why: 'The MOFED driver container logs the exact firmware-version check that fails when out-of-band firmware diverges from the pinned baseline.'},
  {label: 'Host-side firmware truth', command: 'mlxfwmanager -q; mlxconfig -d <device> query', why: 'Read the NIC\'s actual persisted firmware/config state directly from the card, independent of what the operator believes it should be.'},
];
const ibSubnetCommands = [
  {label: 'Subnet manager mastership state', command: 'sminfo', why: 'Directly identify the current SM master GUID and priority, and whether a recent mastership change occurred.'},
  {label: 'OpenSM event log', command: 'grep -Ei \'SUBNET UP|handover|heartbeat|master\' /var/log/opensm.log', why: 'Find the exact takeover/heartbeat-miss sequence that triggered re-routing, rather than treating the outage as a random link flap.'},
  {label: 'Fabric-wide port/topology snapshot', command: 'ibnetdiscover; ibqueryerrors -c', why: 'Confirm no physical link/topology change occurred and that reported errors are transient counters from the reroute window, not sustained link faults.'},
];
const bondingCommands = [
  {label: 'Bond member state', command: 'cat /proc/net/bonding/bond0', why: 'Show per-slave MII status, speed and duplex; a member can report up while negotiated at a lower speed than its peer.'},
  {label: 'Per-NIC link parameters', command: 'ethtool eth0; ethtool eth1', why: 'Confirm negotiated speed/duplex per physical member independently of what the bond driver aggregates and reports as "up".'},
  {label: 'Throughput baseline check', command: 'iperf3 -c <peer> -P 4 -t 20', why: 'Measure actual aggregate throughput against the expected baseline; LACP "up" status alone does not confirm full bandwidth.'},
];
const conntrackCommands = [
  {label: 'Table saturation check', command: 'sysctl net.netfilter.nf_conntrack_count net.netfilter.nf_conntrack_max', why: 'Directly compare current tracked-connection count against the configured ceiling before assuming an application or network fault.'},
  {label: 'Drop evidence', command: 'dmesg -T | grep -i \'nf_conntrack: table full\'; conntrack -L | wc -l', why: 'Confirm the kernel is actively dropping packets due to table exhaustion, not merely close to the limit.'},
  {label: 'Sysctl provenance check', command: 'sysctl -a --pattern nf_conntrack; grep -r nf_conntrack /etc/sysctl.d/ /usr/lib/sysctl.d/', why: 'Determine whether a previously tuned override was reset to a package default after the kernel/OS update, versus never having been set at all.'},
];
const systemdBootCommands = [
  {label: 'Failed-unit state', command: 'systemctl --failed; systemctl status <unit>', why: 'Confirm the unit is in a permanently failed state (retry budget exhausted) rather than merely slow to start.'},
  {label: 'Boot-order dependency graph', command: 'systemd-analyze critical-chain <unit>; systemctl list-dependencies <unit>', why: 'Show the actual After=/Requires= relationships the unit has, or is missing, against the driver-load service/target.'},
  {label: 'Boot-time sequencing evidence', command: 'journalctl -u <unit> -b; journalctl -u nvidia-persistenced -b', why: 'Compare timestamps to confirm the unit attempted to run before the driver-side service reported ready.'},
];
const nhcCommands = [
  {label: 'Health-check outcome vs real GPU state', command: 'sinfo -N -o "%N %T %E"; dcgm-diag -r 3', why: 'Compare what the health check has reported for each node against an independent, manually-run diagnostic before trusting an all-healthy fleet view.'},
  {label: 'Direct script execution', command: 'python3 /path/to/nhc_gpu_check.py --verbose', why: 'Run the health-check logic outside its cron/prolog wrapper to surface an exception the wrapper may be silently swallowing as "healthy."'},
  {label: 'Dependency integrity check', command: 'pip check; pip list --format=freeze | diff - requirements.txt', why: 'Confirm the health-check script\'s own Python environment still matches its pinned dependencies after an unrelated fleet package update.'},
];
const zfsCommands = [
  {label: 'Pool and vdev health', command: 'zpool status -v; zpool list -o name,size,alloc,free,cap,frag,health', why: 'Confirm every vdev is ONLINE with zero read/write/checksum errors before assuming the slowdown is a performance problem rather than a degraded pool.'},
  {label: 'Per-vdev latency and throughput', command: 'zpool iostat -v 1 5', why: 'A degraded or resilvering vdev shows as elevated latency on exactly one device in the pool, not evenly across all of them.'},
  {label: 'ARC cache effectiveness', command: 'arc_summary | head -40; cat /proc/spl/kstat/zfs/arcstats | grep -E "^(hits|misses|c |c_max)"', why: 'A low ARC hit ratio against a cache sized well below c_max means reads are missing cache and hitting disk far more than the workload should require.'},
];

function runbookFor(id: string): Scenario['runbook'] {
  if (['dependency-cascade', 'message-duplicate-processing'].includes(id)) return {containment: 'Protect the user-facing SLO first: bound retries/concurrency, shed non-critical work, and preserve correlation IDs. Do not restart every service in the dependency graph.', commands: serviceCommands, escalation: 'Escalate with impact by operation/tenant, dependency graph, correlation IDs, timeout/retry settings, saturation and error-budget burn, plus the reversible containment already applied.'};
  if (['db-pool-exhaustion', 'backup-restore-corrupt'].includes(id)) return {containment: 'Reduce nonessential database demand and preserve server/pool evidence. Do not raise max connections or promote an unvalidated restore until capacity, locks, consistency and rollback are understood.', commands: databaseCommands, escalation: 'Escalate with database/pool limits, active and waiting sessions, oldest transactions, query/lock evidence, replica/backup state, RPO/RTO impact and validation results.'};
  if (['lb-keepalive-502', 'nat-port-exhaustion'].includes(id)) return {containment: 'Limit retry amplification and fail traffic only to a verified healthy path. Do not flush connection tracking, change global timeouts, or bypass TLS without a bounded test and rollback.', commands: edgeNetworkCommands, escalation: 'Escalate with affected source/destination/region, DNS result, TCP/TLS timings, LB/backend codes, socket/conntrack/NAT counters, flow logs and the last network or timeout change.'};
  if (['deployment-schema-rollback', 'cicd-runner-starvation', 'gitops-mutating-webhook-loop'].includes(id)) return {containment: 'Pause the specific rollout or reconciliation actor while keeping known-good workloads serving. Preserve revision, image digest, migration and policy evidence before forcing state.', commands: deliveryCommands, escalation: 'Escalate with commit/image/config revisions, rollout and pipeline timestamps, schema/event compatibility, gate results, queue/capacity evidence, rollback boundary and owner decision.'};
  if (['kafka-lag-hot-partition'].includes(id)) return {containment: 'Protect producer and consumer SLOs, avoid blind partition reassignment, and preserve per-partition offsets and ownership before scaling consumers.', commands: streamingCommands, escalation: 'Escalate with topic/group, lag and throughput per partition, key distribution, leader/ISR state, rebalance history, processing latency and replay/idempotency plan.'};
  if (['cache-stampede'].includes(id)) return {containment: 'Rate-limit cache-miss work and protect the origin. Avoid flushing the entire cache or adding replicas that multiply misses.', commands: cacheCommands, escalation: 'Escalate with hit/miss/eviction rates, hot keys, TTL distribution, origin amplification, connection/memory state and proposed single-flight or stale-serving mitigation.'};
  if (['disk-inode-exhaustion', 'noisy-neighbor-steal', 'clock-skew-oidc'].includes(id)) return {containment: 'Protect the affected service and preserve host evidence before rebooting, deleting files, moving workloads or changing system time abruptly.', commands: linuxCommands, escalation: 'Escalate with host/VM identity, pressure and process evidence, filesystem bytes/inodes, hypervisor or time-source state, affected services and the most recent host/platform change.'};
  if (['terraform-lock-orphan'].includes(id)) return {containment: 'Stop concurrent applies and verify no live Terraform process owns the lock. Never force-unlock solely because a pipeline timed out.', commands: terraformCommands, escalation: 'Escalate with workspace/backend, lock ID and owner, pipeline/process state, state version, last successful apply, cloud audit evidence and recovery/rollback plan.'};
  if (['gpu-unavailable', 'driver-mismatch', 'mig', 'xid', 'low-gpu', 'topology'].includes(id)) return {containment: 'Avoid rescheduling blindly onto the same suspect node. Cordon it for a node-local driver or hardware signal; drain only when workload disruption is approved and a checkpoint/redundancy plan exists.', commands: gpuCommands, escalation: 'Escalate with node name, GPU UUID/PCI bus ID, driver and CUDA versions, Xid/NVRM excerpt, device-plugin logs, and the exact workload image digest.'};
  if (['nccl', 'roce', 'rdma-perf', 'scaling'].includes(id)) return {containment: 'Stop expanding the affected distributed job and preserve logs. Do not change global fabric PFC/ECN, routing, or NCCL defaults without network-owner approval and a rollback plan.', commands: fabricCommands, escalation: 'Escalate with affected node pairs/rack or rail, NCCL log timestamps, interface/IP mapping, link state/rate, counter deltas, and a known-good baseline.'};
  if (['notready'].includes(id)) return {containment: 'Cordon the node first to prevent new placement. Preserve disk and journal evidence before deleting images, restarting containerd, or rebooting.', commands: nodeCommands, escalation: 'Escalate with node conditions, filesystem byte/inode use, kubelet/container-runtime logs, image-GC state, and scope of affected workloads.'};
  if (['high-load', 'memory-reclaim', 'fd-exhaustion', 'tls-expiry'].includes(id)) return {containment: 'Protect the affected service from additional load and preserve host evidence. Avoid rebooting or killing processes until ownership, redundancy, and recoverability are understood.', commands: linuxCommands, escalation: 'Escalate with host/service identity, start of impact, process state, PSI/vmstat/pidstat evidence, relevant journal entries, limits, dependency state, and the last change.'};
  if (['api-etcd', 'gitops-drift'].includes(id)) return {containment: 'Freeze nonessential control-plane mutations and automated reconciliation only when the blast radius justifies it. Preserve audit logs and revision/change context.', commands: controlPlaneCommands, escalation: 'Escalate with API readiness, latency by verb/resource, inflight requests, etcd endpoint/quorum state, audit evidence, Git revision, and safe rollback decision.'};
  if (['retry-storm', 'partial-automation'].includes(id)) return {containment: 'Pause the specific automation actor or reduce its concurrency; do not disable unrelated controllers. Record correlation IDs and partial mutations before retrying.', commands: automationCommands, escalation: 'Escalate with tool version, invocation inputs, dry-run/diff, structured logs, attempts and deadline metrics, partial-success inventory, idempotency evidence, and rollback plan.'};
  if (['missing-gpu-metrics', 'cardinality'].includes(id)) return {containment: 'Treat missing telemetry as unknown—not healthy. Protect alerting and query capacity while preserving the scrape/export pipeline evidence.', commands: observabilityCommands, escalation: 'Escalate with affected metric/target, scrape and exporter logs, label/cardinality deltas, query timing, retention/remote-write state, and the last dashboard or instrumentation change.'};
  if (['slurm-pending', 'slurm-fairshare-starve', 'slurm-failover-lost-jobs'].includes(id)) return {containment: 'Do not cancel and resubmit repeatedly or drain nodes to force placement. Preserve the exact job request, pending reason, and controller/accounting state.', commands: slurmCommands, escalation: 'Escalate with job ID, partition/QOS/account, GRES/TRES and constraints, pending reason/priority, eligible node state, reservation/dependency, and capacity owner.'};
  if (id === 'bmc-unreachable-fw-update') return {containment: 'Do not power-cycle blindly while an update is in flight — a forced power event mid-flash can brick the BMC. Attempt out-of-band console access before any power action.', commands: bmcCommands, escalation: 'Escalate with BMC firmware version before/after, Redfish Task resource state, vendor support case if the BMC is unresponsive to all paths, and physical-access owner for the rack.'};
  if (id === 'pxe-boot-after-rma') return {containment: 'Do not swap in a different NIC or reflash BIOS speculatively before the DHCP/TFTP capture confirms which stage is failing. Work the D-T-B-I decomposition in order.', commands: pxeCommands, escalation: 'Escalate with node serial/MAC before and after RMA, DHCP/TFTP capture excerpt, provisioning-system registration status, and boot-mode (BIOS/UEFI) setting.'};
  if (id === 'bcm-category-drift') return {containment: 'Do not force a category re-push blindly onto a hand-edited node — reconcile the diff first so the push does not silently clobber an intentional emergency fix.', commands: bcmCommands, escalation: 'Escalate with category name, image version, the exact node-level diff, who made the manual edit and why, and whether other nodes in the category are similarly affected.'};
  if (id === 'ansible-false-idempotent') return {containment: 'Stop treating changed= as noise. Freeze further re-runs against the affected role until the ordering source is identified, so a real unauthorized change is not lost inside a known-false-positive signal.', commands: ansibleCommands, escalation: 'Escalate with the templated task name, three consecutive --check --diff outputs, the source dict/merge structure, and the affected node list.'};
  if (id === 'terraform-state-drift-destroy') return {containment: 'Do not apply a plan showing an unexpected -/+ on a resource nobody intended to touch. Treat that marker as an automatic stop for manual review, regardless of how routine the rest of the plan looks.', commands: terraformCommands, escalation: 'Escalate with the resource address, the manual change that caused drift, the exact attribute forcing replacement, and whether the resource holds unrecoverable data.'};
  if (id === 'mpi-nccl-startup-hang') return {containment: 'Do not restart the job repeatedly without first determining which side of the MPI/NCCL handoff point it stalled at — a blind retry burns allocation time without new information.', commands: mpiCommands, escalation: 'Escalate with job ID, per-rank bootstrap/bindings output, the last NCCL_DEBUG line per rank, and node/rail pairing for the stalled rank.'};
  if (id === 'enroot-gpu-not-visible') return {containment: 'Confirm the host GPU path is healthy before touching Enroot config, so a driver fix is not mistakenly attempted for a container-runtime problem.', commands: enrootCommands, escalation: 'Escalate with node name, hook file presence/version, NVIDIA_VISIBLE_DEVICES value inside the container, and whether Kubernetes GPU workloads on the same node are unaffected.'};
  if (['selinux-gpu-monitoring-block', 'os-hardening-breaks-rdma'].includes(id)) return {containment: 'Do not disable enforcement or the profile fleet-wide to make the symptom disappear. Treat setenforce 0/complain mode as a temporary diagnostic step only, with a tracked follow-up.', commands: selinuxCommands, escalation: 'Escalate with the exact AVC denial or sysctl/firewall diff, the audit2why explanation, the hardening baseline version applied, and the compensating-control owner if a risk-acceptance decision is needed.'};
  if (id === 'canary-firmware-not-representative') return {containment: 'Halt further rollout waves immediately. Do not resume based on the canary\'s prior pass — that evidence no longer covers the hardware variant now failing.', commands: changeMgmtCommands, escalation: 'Escalate with the compatibility matrix, canary stratification criteria used, the specific firmware revision affected, and the percentage of fleet on that revision.'};
  if (id === 'cicd-emergency-override-bypass') return {containment: 'Freeze further use of the override path pending audit. Do not treat the applied change as validated just because it succeeded technically.', commands: cicdCommands, escalation: 'Escalate with the override justification on record (or its absence), the policy rule that was bypassed, the blast radius of what was actually applied, and the recovery/rollback plan.'};
  if (id === 'kernel-patch-dkms-break') return {containment: 'Do not reboot the remaining batches into the new kernel until the DKMS rebuild gate is confirmed working. Hold the patch wave at its current batch.', commands: dkmsCommands, escalation: 'Escalate with kernel version before/after, dkms status output, affected node count in the batch, and whether untouched batches can be safely held.'};
  if (id === 'lustre-mds-metadata-bottleneck') return {containment: 'Throttle or pause concurrent checkpoint writers to relieve MDS RPC pressure immediately. Do not add OSTs or OST bandwidth, since a metadata-bound bottleneck is unaffected by more throughput capacity.', commands: lustreCommands, escalation: 'Escalate with md_stats RPC-rate deltas, affected MDT name, checkpoint file-count-per-step, and whether DNE/striped metadata capacity is available to absorb the load.'};
  if (id === 'gpfs-quorum-loss-rolling-upgrade') return {containment: 'Restore the maintenance node to the network (or promote a standby quorum node) immediately to reestablish majority quorum. Do not attempt to force cluster state or restart file-system managers while below quorum.', commands: gpfsCommands, escalation: 'Escalate with configured quorum node count and current reachable count, mmgetstate -a output fleet-wide, the maintenance window plan, and whether a spare quorum node can be added before the next upgrade wave.'};
  if (id === 'xfs-inode-exhaustion-checkpoint-shard') return {containment: 'Delete only confirmed superseded/expired checkpoint shards through the approved retention process to free inodes immediately. Do not delete active or unverified checkpoints, and do not resize the filesystem live.', commands: xfsCommands, escalation: 'Escalate with df -i utilization, xfs_db inode counts, the checkpoint-sharding file-count pattern, and the retention window that can be safely reclaimed.'};
  if (id === 'grafana-stale-healthy-dashboard') return {containment: 'Treat a target reporting up=0 or a stale lastScrape timestamp as an active outage regardless of what the last rendered panel value shows. Fix the scrape/service-discovery configuration rather than refreshing the dashboard.', commands: grafanaCommands, escalation: 'Escalate with the affected job/target, lastScrape age, the service-discovery/relabel change that preceded the gap, and how long the stale value was displayed as healthy.'};
  if (id === 'loki-label-cardinality-collapse') return {containment: 'Roll back or patch the log pipeline to stop promoting per-request/per-job unique fields to labels immediately. Do not scale ingesters to absorb the stream count, since the label design itself is unbounded.', commands: lokiCommands, escalation: 'Escalate with the offending label name and distinct-value count, ingester memory/stream-count trend, the pipeline release that introduced it, and the rollback/relabel plan.'};
  if (id === 'network-operator-nic-firmware-drift') return {containment: 'Do not delete/recreate the NicClusterPolicy or restart the operator broadly. Reconcile the single source of truth on the specific affected nodes only: either roll the out-of-band firmware back or update the CR to match it.', commands: networkOperatorCommands, escalation: 'Escalate with the NicClusterPolicy pinned firmware/driver version, the mlxfwmanager-reported actual version, affected node list, and who applied the out-of-band update.'};
  if (id === 'ib-subnet-manager-failover') return {containment: 'Do not intervene on individual jobs or nodes during the event. Confirm via sminfo/opensm logs that this is an SM mastership failover and let the new master complete re-routing before investigating the primary.', commands: ibSubnetCommands, escalation: 'Escalate with the SM master GUID change timestamp, prior master heartbeat-miss evidence, affected racks/partitions, and current SM priority/polling configuration.'};
  if (id === 'bonded-nic-silent-half-bandwidth') return {containment: 'Identify and isolate the degraded bond member; do not just restart the bond or reboot blindly. Force a renegotiation or remove the degraded link from the active set if it cannot be restored immediately.', commands: bondingCommands, escalation: 'Escalate with per-member negotiated speed/duplex, the driver version before/after the update, iperf3 baseline versus current throughput, and affected node count in the maintenance batch.'};
  if (id === 'conntrack-table-full-kernel-update') return {containment: 'Raise net.netfilter.nf_conntrack_max (and buckets proportionally) back to the previously validated value immediately. Do not disable connection tracking or the firewall to work around the symptom.', commands: conntrackCommands, escalation: 'Escalate with the kernel/OS patch version before/after, nf_conntrack_count versus nf_conntrack_max at time of drops, the sysctl override that was reset, and the persistence mechanism to prevent recurrence.'};
  if (id === 'systemd-gpu-service-race-boot-order') return {containment: 'Manually restart the failed service now (systemctl reset-failed && systemctl restart) to restore monitoring immediately, then fix the unit ordering so it survives the next reboot.', commands: systemdBootCommands, escalation: 'Escalate with the unit\'s current After=/Requires= dependencies, journalctl boot-time sequencing evidence, StartLimitBurst configuration, and affected node count across the fleet.'};
  if (id === 'slurm-healthcheck-venv-false-green') return {containment: 'Rebuild/repair the health-check script\'s Python environment on affected nodes immediately, and manually run dcgm-diag/fabric checks fleet-wide to find nodes the broken health check missed while it was silently failing.', commands: nhcCommands, escalation: 'Escalate with the exact traceback/ModuleNotFoundError, the package update that broke the venv, how long the health check has been silently passing, and the fleet-wide scope of nodes needing a manual re-check.'};
  if (id === 'dcgm-scrape-target-down-masked-by-average') return {containment: 'Restart or repair the specific node\'s dcgm-exporter/scrape path and confirm the target returns to up=1. Do not treat the fleet-average panel as evidence the fleet is fully instrumented.', commands: observabilityCommands, escalation: 'Escalate with the affected node/instance, lastScrape age, count(up{job="dcgm-exporter"}==0), and how long the gap was hidden behind the averaged panel.'};
  if (id === 'zfs-arc-undersized-checkpoint-cache-thrash') return {containment: 'Do not resize the ARC or reboot the node while the pool is actively resilvering or under checkpoint load — confirm pool health first, since an undersized cache and a degraded vdev produce a similar-looking slowdown but need opposite responses.', commands: zfsCommands, escalation: 'Escalate with zpool status output, ARC hit-ratio trend, c_max versus system RAM, and the checkpoint write-burst schedule that coincides with the slowdown.'};
  if (id === 'cgroup-namespace-leak-zombie-pod-resources') return {containment: 'Do not force-delete the cgroup directory or kill the kernel-held process by PID alone — identify which namespace/cgroup is actually leaked first, since removing the wrong one can orphan a still-running workload\'s accounting.', commands: linuxCommands, escalation: 'Escalate with the leaked cgroup path, the PID(s) still resident in it, container runtime logs for the Pod\'s reported termination time, and how many leaked cgroups have accumulated on the node.'};
  return {containment: 'Start with a canary or the smallest affected scope. Prefer reversible configuration changes; do not delete Pods, PVCs, or data to make the symptom disappear.', commands: kubectlPodCommands, escalation: 'Escalate with impact and timeline, exact object events, manifests or relevant diff, logs/metrics for the failing window, changes already attempted, and a safe rollback point.'};
}

function categoryFor(id: string): string {
  if (['dependency-cascade', 'message-duplicate-processing'].includes(id)) return 'Distributed Systems';
  if (['db-pool-exhaustion', 'cache-stampede', 'backup-restore-corrupt'].includes(id)) return 'Database & Cache';
  if (['lb-keepalive-502', 'nat-port-exhaustion'].includes(id)) return 'Cloud Networking';
  if (['deployment-schema-rollback', 'cicd-runner-starvation', 'gitops-mutating-webhook-loop'].includes(id)) return 'CI/CD & Delivery';
  if (['kafka-lag-hot-partition'].includes(id)) return 'Messaging & Streaming';
  if (['disk-inode-exhaustion', 'noisy-neighbor-steal'].includes(id)) return 'Linux/Systems';
  if (['clock-skew-oidc'].includes(id)) return 'Security/IAM';
  if (['terraform-lock-orphan'].includes(id)) return 'IaC (Ansible/Terraform)';
  if (['crashloop', 'pending', 'notready', 'oom', 'cpu-throttle', 'dns', 'network-policy', 'pvc', 'hpa', 'api-etcd', 'gitops-drift'].includes(id)) return 'Kubernetes';
  if (['gpu-unavailable', 'driver-mismatch', 'mig', 'xid', 'ttft', 'low-gpu'].includes(id)) return 'GPU/Driver';
  if (['nccl', 'roce', 'rdma-perf', 'scaling', 'topology'].includes(id)) return 'Networking/Fabric';
  if (['storage'].includes(id)) return 'Storage & Data';
  if (['high-load', 'memory-reclaim', 'fd-exhaustion'].includes(id)) return 'Linux/Systems';
  if (['retry-storm', 'partial-automation'].includes(id)) return 'Automation & Python';
  if (['missing-gpu-metrics', 'cardinality'].includes(id)) return 'Observability';
  if (['tls-expiry'].includes(id)) return 'Security';
  if (['bmc-unreachable-fw-update', 'pxe-boot-after-rma', 'bcm-category-drift'].includes(id)) return 'Bare-metal/BCM';
  if (['ansible-false-idempotent', 'terraform-state-drift-destroy'].includes(id)) return 'IaC (Ansible/Terraform)';
  if (['slurm-pending', 'slurm-fairshare-starve', 'slurm-failover-lost-jobs', 'mpi-nccl-startup-hang', 'enroot-gpu-not-visible'].includes(id)) return 'Slurm/HPC';
  if (['selinux-gpu-monitoring-block', 'kernel-patch-dkms-break', 'os-hardening-breaks-rdma'].includes(id)) return 'Security';
  if (['canary-firmware-not-representative', 'cicd-emergency-override-bypass'].includes(id)) return 'Change Management';
  if (['lustre-mds-metadata-bottleneck', 'gpfs-quorum-loss-rolling-upgrade', 'xfs-inode-exhaustion-checkpoint-shard'].includes(id)) return 'Storage & Data';
  if (['grafana-stale-healthy-dashboard', 'loki-label-cardinality-collapse', 'dcgm-scrape-target-down-masked-by-average'].includes(id)) return 'Observability';
  if (['zfs-arc-undersized-checkpoint-cache-thrash'].includes(id)) return 'Storage & Data';
  if (['cgroup-namespace-leak-zombie-pod-resources'].includes(id)) return 'Linux/Systems';
  if (['network-operator-nic-firmware-drift', 'ib-subnet-manager-failover'].includes(id)) return 'Networking/Fabric';
  if (['bonded-nic-silent-half-bandwidth', 'conntrack-table-full-kernel-update', 'systemd-gpu-service-race-boot-order'].includes(id)) return 'Linux/Systems';
  if (['slurm-healthcheck-venv-false-green'].includes(id)) return 'Slurm/HPC';
  return 'Kubernetes';
}

const make = (id: string, title: string, description: string, root: string, evidence: string[], mitigation: string, prevention: string): Scenario => ({
  id, title, description, expectedRootCause: root,
  learningObjectives: ['Form competing hypotheses', 'Choose high-information checks', 'Separate symptom, cause, mitigation, and prevention'],
  evidence: [
    {action: 'Establish scope and recent change', output: evidence[0], interpretation: 'Use blast radius and timing to rank hypotheses.'},
    {action: 'Inspect workload and control-plane evidence', output: evidence[1], interpretation: 'Object state narrows the failing lifecycle boundary.'},
    {action: 'Inspect node, runtime, and dependency evidence', output: evidence[2], interpretation: 'Correlate host evidence with the workload symptom.'},
    {action: 'Run the targeted validation', output: evidence[3], interpretation: 'Validate the leading hypothesis before mitigation.'},
  ], mitigation, prevention, runbook: runbookFor(id), category: categoryFor(id),
});

export const scenarios: Scenario[] = [
  make('crashloop', 'CrashLoopBackOff', 'A new API Pod repeatedly restarts after rollout.', 'A required config key was renamed; the process exits during startup.', ['Only the new ReplicaSet fails after a config rollout.', 'Last termination: exit 1; events show exponential restart backoff.', 'Container log: KeyError DATABASE_URL; Secret contains DB_URL.', 'A canary with the corrected key becomes Ready.'], 'Restore the compatible key and roll back or restart safely.', 'Schema-check configuration in CI and use startup probes deliberately.'),
  make('pending', 'Pending Pod', 'A GPU workload remains Pending although the cluster has idle CPU.', 'No node has the requested GPU resource and required topology label together.', ['Only GPU jobs with zone affinity are affected.', 'FailedScheduling: insufficient nvidia.com/gpu and affinity mismatch.', 'GPU nodes are Ready; the requested zone contains CPU-only nodes.', 'Removing affinity schedules; placing GPU capacity in-zone also succeeds.'], 'Correct the constraint or provide matching capacity.', 'Validate placement constraints against capacity inventory.'),
  make('notready', 'Node NotReady', 'One worker stops accepting Pods.', 'Disk pressure filled the runtime filesystem and kubelet stopped reporting.', ['A single node is affected after image churn.', 'Node condition Ready=Unknown; DiskPressure=True.', 'journalctl shows image GC failures; /var/lib/containerd is full.', 'Freeing safe reclaimable images restores kubelet heartbeats.'], 'Cordon, reclaim runtime disk safely, restart only if required, then uncordon after validation.', 'Reserve disk, alert on inode/space pressure, and tune image GC.'),
  make('oom', 'OOMKilled', 'An inference container is killed under burst load.', 'KV-cache growth exceeds the container memory limit.', ['Failures correlate with long-context traffic.', 'Last state OOMKilled; memory limit is 16Gi.', 'Working set climbs with active sequence tokens; node has free memory.', 'Capping tokens/concurrency keeps the cgroup below its limit.'], 'Reduce concurrency/context or raise the evidence-based limit.', 'Capacity-test KV cache and expose token-weighted saturation metrics.'),
  make('cpu-throttle', 'CPU throttling', 'Latency rises while CPU utilization looks moderate.', 'A low CPU limit causes CFS quota throttling during bursts.', ['Only latency-sensitive sidecars with limits regress.', 'Pod CPU is below one core on average.', 'cpu.stat shows rapidly rising nr_throttled and throttled_usec.', 'A canary with a justified limit/removal restores tail latency.'], 'Adjust the CPU limit after safety review.', 'Track throttling and size limits from burst demand, not averages.'),
  make('dns', 'DNS failure', 'Pods intermittently fail service-name lookups.', 'CoreDNS is saturated and dropping/queuing queries.', ['Cross-namespace DNS fails during deployment bursts.', 'Services and EndpointSlices are correct.', 'CoreDNS CPU throttles; request duration and SERVFAIL rise.', 'Scaling CoreDNS and removing its restrictive CPU limit clears failures.'], 'Restore DNS capacity and verify caching behavior.', 'Monitor DNS latency/errors and capacity-test query bursts.'),
  make('network-policy', 'NetworkPolicy denial', 'A newly deployed namespace cannot reach a shared API.', 'Default-deny was added without an egress allow rule.', ['Only the new namespace fails after policy rollout.', 'Service discovery succeeds; TCP connect times out.', 'CNI policy counters show denied egress to the API namespace.', 'A narrowly scoped egress rule restores the canary.'], 'Add least-privilege egress for the required destination/port.', 'Test policy intent in staging and maintain ownership metadata.'),
  make('pvc', 'PVC Pending', 'A StatefulSet cannot start because its claim is Pending.', 'The requested StorageClass uses delayed binding but no schedulable topology satisfies the Pod.', ['Claims using one zonal class are affected.', 'PVC: WaitForFirstConsumer; Pod: topology conflict.', 'No eligible node exists in the PV provisioner zone.', 'Adding eligible capacity or changing the valid topology binds the claim.'], 'Align node, workload, and storage topology.', 'Continuously reconcile zonal capacity with storage classes.'),
  make('hpa', 'HPA not scaling', 'Request rate climbs but replicas stay fixed.', 'The custom metric adapter returns no series because labels changed.', ['Only the custom-metric HPA is affected.', 'HPA condition ScalingActive=False; metric unknown.', 'Adapter query returns empty after application label rename.', 'Corrected selector returns values and desired replicas increases.'], 'Fix the metric selector and observe controlled scaling.', 'Contract-test metrics and alert on invalid HPA conditions.'),
  make('gpu-unavailable', 'GPU unavailable', 'A Pod requests a GPU but nodes advertise none.', 'The NVIDIA device plugin is crash-looping after driver initialization failure.', ['All Pods on one GPU pool are Pending.', 'Allocatable nvidia.com/gpu is absent.', 'Device-plugin log cannot load NVML; nvidia-smi fails on host.', 'Restoring the validated driver makes NVML and allocatable resources return.'], 'Cordon affected nodes and restore the known-good driver stack.', 'Use GPU Operator readiness and golden-node validation.'),
  make('driver-mismatch', 'GPU driver mismatch', 'CUDA workloads fail immediately after a node image update.', 'The container CUDA requirement is newer than the installed driver supports.', ['Only newer workload images fail on updated scheduling.', 'Container reports CUDA driver version insufficient.', 'nvidia-smi driver version is below the image compatibility floor.', 'Known-compatible image succeeds on the same node.'], 'Roll back the image or upgrade the driver through the validated lifecycle.', 'Enforce a driver/CUDA compatibility matrix in admission and release tests.'),
  make('mig', 'MIG resource issue', 'A Pod requesting a MIG profile never schedules.', 'Nodes are partitioned into a different MIG geometry than requested.', ['Only one MIG resource profile is unavailable.', 'FailedScheduling reports insufficient nvidia.com/mig-2g.20gb.', 'nvidia-smi mig -lgi shows only 1g and 3g instances.', 'Reconfiguring a drained test node to the required geometry advertises the resource.'], 'Drain and reconcile the approved MIG geometry.', 'Treat MIG layouts as capacity products with demand forecasting.'),
  make('xid', 'Xid error', 'Training processes disappear on one host.', 'A repeatable GPU hardware/PCIe fault produces Xid events.', ['Failures follow one GPU UUID across jobs.', 'Pod exits non-zero without application error.', 'dmesg records repeated NVRM Xid for that UUID.', 'DCGM diagnostics reproduce the fault after drain.'], 'Drain/quarantine the GPU node and follow hardware remediation guidance.', 'Alert on actionable Xid classes and retain UUID-to-node history.'),
  make('nccl', 'NCCL timeout', 'Multi-node training hangs during collective initialization.', 'One rail is unreachable because its interface has the wrong subnet configuration.', ['Single-node jobs pass; multi-node jobs on rail 2 fail.', 'NCCL log times out connecting one peer address.', 'ip route and ibdev2netdev show rail-2 subnet mismatch.', 'Corrected test interface passes nccl-tests across nodes.'], 'Repair rail configuration and restart from a safe checkpoint.', 'Validate every rail preflight and monitor fabric reachability.'),
  make('roce', 'RoCE misconfiguration', 'RDMA traffic has loss and unstable throughput.', 'Priority flow control is inconsistent across a switch hop.', ['Only the RoCE VLAN degrades under load.', 'Application retransmission/retry counters rise.', 'Switch/NIC counters show pause mismatch and ECN imbalance.', 'A controlled fabric config correction stabilizes perftest.'], 'Align the end-to-end lossless/ECN configuration with network ownership.', 'Automate fabric conformance tests and configuration drift checks.'),
  make('rdma-perf', 'RDMA performance issue', 'RDMA connects but bandwidth is far below baseline.', 'Traffic crosses the wrong NUMA socket between GPU and NIC.', ['One node pair is slow; link state is healthy.', 'ib_write_bw is lower only with the workload binding.', 'nvidia-smi topo -m and numactl show remote NIC/GPU affinity.', 'Binding CPU/GPU/NIC locally restores the baseline.'], 'Correct topology-aware placement and process binding.', 'Publish topology labels and test affinity after hardware changes.'),
  make('storage', 'Storage bottleneck', 'GPU utilization periodically collapses during training.', 'Dataset reads saturate shared storage metadata and throughput.', ['All workers stall at epoch boundaries.', 'GPU duty cycle drops while CPUs wait.', 'iostat and storage telemetry show latency/queue spikes; network is healthy.', 'Cached/sharded data sustains GPU utilization in a controlled run.'], 'Stage or shard data and reduce synchronized metadata pressure.', 'Benchmark the complete data pipeline and size storage to feed GPUs.'),
  make('scaling', 'Training scaling failure', 'Adding nodes yields little throughput improvement.', 'Collective communication dominates because the fabric is oversubscribed.', ['Single-node throughput is normal; efficiency falls with node count.', 'Step traces show AllReduce duration growing sharply.', 'Fabric links are healthy but uplinks saturate at the job boundary.', 'A topology-contained allocation improves scaling efficiency.'], 'Place the job within a suitable fabric domain or reduce communication.', 'Model collective bandwidth and reserve non-oversubscribed capacity.'),
  make('ttft', 'Inference TTFT regression', 'Time to first token doubles while tokens/sec remains stable.', 'Prefill requests queue behind long prompts after batching policy changed.', ['TTFT regresses for long prompts; decode TPOT is unchanged.', 'Server queue time and prefill batch size increased after rollout.', 'GPU is busy; KV capacity is healthy; no network regression.', 'Separating/capping prefill batches restores TTFT in canary.'], 'Roll back or tune prefill scheduling with SLO guardrails.', 'Track queue, prefill, decode, prompt length, TTFT, and TPOT separately.'),
  make('low-gpu', 'Low GPU utilization', 'A training job reports 35% GPU utilization.', 'CPU data preprocessing cannot feed the GPU fast enough.', ['All GPUs dip together between steps.', 'Profiler shows gaps before host-to-device copies.', 'CPU workers saturate; storage and collective links are below capacity.', 'More/tuned loader workers and pinned memory reduce gaps.'], 'Tune or move preprocessing after validating the bottleneck.', 'Include input-pipeline profiling in performance qualification.'),
  make('topology', 'Topology / NUMA issue', 'One of eight GPUs is consistently slower.', 'The Pod CPU set and NIC are remote to that GPU’s NUMA domain.', ['The slowdown follows rank placement, not model data.', 'Per-rank step time isolates rank 7.', 'Topology and cpuset evidence shows remote memory/NIC path.', 'Topology-aligned placement normalizes the rank.'], 'Rebind or reschedule using topology-aware resources.', 'Expose NUMA/PCIe topology and validate rank mapping.'),
  make('high-load', 'Linux high load, idle CPU', 'A model gateway has load average 40 on 16 CPUs while CPU utilization stays below 25%.', 'Many worker threads are stuck in uninterruptible I/O against a degraded network filesystem.', ['Only hosts mounting one dataset path are affected after storage maintenance.', 'Application latency rises, but Kubernetes CPU metrics and HPA remain calm.', 'vmstat b and PSI I/O rise; processes are D-state in an NFS wait function.', 'A controlled request against local storage avoids the stall while the NFS path reproduces it.'], 'Shift traffic or data access away from the degraded path and coordinate storage recovery.', 'Alert on PSI and D-state/latency signals; capacity-test and isolate critical dependency paths.'),
  make('memory-reclaim', 'Linux memory reclaim storm', 'A node is responsive but latency spikes every few minutes and no process has been OOM-killed.', 'A page-cache/anonymous-memory working set exceeds safe capacity, causing direct reclaim and major faults.', ['Nodes with the newest data-loader configuration regress.', 'Pods remain Running; p99 latency spikes without restarts.', 'PSI memory, pgmajfault and direct reclaim rise; swap or cgroup memory pressure is sustained.', 'Reducing loader cache/concurrency on one canary removes reclaim stalls.'], 'Reduce the proven working set or move load; change limits only with capacity evidence.', 'Track PSI, faults, reclaim and working-set composition; load-test memory behavior, not just steady RSS.'),
  make('fd-exhaustion', 'File descriptor exhaustion', 'A Python control service begins returning “too many open files” after several hours.', 'HTTP response bodies/sessions are not closed, leaking sockets until RLIMIT_NOFILE is reached.', ['Only long-running replicas fail; restart temporarily clears symptoms.', 'Readiness fails and client errors show EMFILE.', '/proc/<pid>/fd count grows monotonically; most descriptors are sockets to one API.', 'A canary using context-managed sessions keeps descriptor count stable.'], 'Fail over or restart only after preserving evidence, then deploy the resource-lifecycle fix.', 'Use context managers/pools, bound concurrency, alert on FD utilization, and test repeated execution.'),
  make('retry-storm', 'Python automation retry storm', 'A cluster inventory job turns an API slowdown into a control-plane outage.', 'Every client retries 429/503 responses immediately without jitter, deadline, or concurrency limits.', ['API saturation starts seconds after the inventory schedule fires.', 'Requests multiply while successful inventory completions fall.', 'Structured logs show synchronized attempts; inflight requests and 429s climb together.', 'A canary with retry budget, jitter and concurrency cap completes without amplification.'], 'Pause the job or sharply reduce concurrency, then resume with bounded retry policy.', 'Centralize API client policy; test 429/503 behavior and monitor amplification/deadline exhaustion.'),
  make('partial-automation', 'Partial infrastructure automation failure', 'A Python remediation updates half the nodes, fails, and is then rerun.', 'The workflow is not idempotent and has no durable per-target operation state.', ['Only targets after a specific API timeout are inconsistent.', 'The rerun reports conflicts on already-mutated nodes.', 'Logs lack correlation/target state; dry-run differs from both intended and actual state.', 'A redesigned canary records planned/applied/verified states and safely resumes.'], 'Stop repeated execution, inventory actual state, and reconcile each target through an approved plan.', 'Use idempotent operations, checkpoints, structured results, dry-run, verification, and partial-failure tests.'),
  make('api-etcd', 'Kubernetes API and etcd latency', 'kubectl, controllers, and scheduling slow down across the cluster.', 'A high-cardinality controller list/watch pattern plus slow etcd storage drives API request latency.', ['All namespaces are affected after a new controller rollout.', 'Controller work queues grow; API requests time out across resource types.', 'apiserver inflight/latency and etcd fsync/backend latency rise; quorum remains healthy.', 'Scaling back the controller and stopping its broad relists reduces request and storage pressure.'], 'Roll back or rate-limit the offending client and protect control-plane capacity.', 'Use efficient watches/indexes, API priority/fairness, client budgets, etcd SLOs, and rollout load tests.'),
  make('gitops-drift', 'GitOps reconciliation drift', 'A production setting keeps reverting minutes after operators repair it.', 'Two reconcilers own the same field: GitOps desired state conflicts with an operator/defaulting controller.', ['Only one resource kind drifts after enabling a new operator.', 'Managed fields show alternating managers and repeated updates.', 'Git revision is stable; audit events show two controllers writing the same field.', 'Assigning single ownership in a canary stops the reconciliation loop.'], 'Pause the narrower conflicting reconciliation and restore one authoritative desired state.', 'Define field ownership, admission policy, change paths, and drift alerts; test operator/GitOps interaction.'),
  make('tls-expiry', 'TLS certificate expiry', 'Pods resolve a dependency and establish TCP, but TLS handshakes suddenly fail.', 'The dependency certificate expired because rotation updated storage but not the serving process.', ['All callers fail at the same time; DNS and TCP remain healthy.', 'Clients report certificate expired/not yet valid rather than timeout.', 'openssl s_client shows the expired served certificate; the secret contains a newer certificate.', 'Reloading a canary endpoint serves the new chain and succeeds with hostname verification.'], 'Reload/restart the serving process through its safe procedure or fail over to a valid endpoint.', 'Monitor served-certificate expiry, test rotation/reload, preserve chain/SAN validation, and alert before the renewal window.'),
  make('missing-gpu-metrics', 'Missing DCGM GPU metrics', 'Dashboards show zero GPU utilization for a busy node pool.', 'dcgm-exporter cannot reach the host engine after a NetworkPolicy change; zero is actually missing telemetry.', ['Only one namespace/node pool loses data after policy rollout.', 'Workloads and nvidia-smi show activity while Prometheus panels appear empty/zero.', 'Prometheus target is down and exporter logs show connection failure; DCGM itself is healthy.', 'A least-privilege connectivity rule restores a canary target and real samples.'], 'Restore exporter-to-DCGM connectivity and mark gaps as unknown in dashboards.', 'Alert on target absence/staleness, test telemetry policies, and distinguish zero from missing data.'),
  make('cardinality', 'Prometheus cardinality explosion', 'Prometheus query latency and memory usage spike after a deployment.', 'A request ID was added as a metric label, creating an effectively unbounded time-series dimension.', ['Monitoring degrades immediately after one instrumentation release.', 'Ingestion and head-series count surge; application traffic is normal.', 'Label-value analysis identifies request_id on a high-rate metric.', 'Dropping the label in a canary/collector reduces new-series creation and query latency.'], 'Roll back/drop the unbounded label and protect Prometheus query/ingestion capacity.', 'Enforce label budgets and instrumentation review; use logs/traces for high-cardinality identifiers.'),
  make('slurm-pending', 'Slurm GPU job remains Pending', 'An eight-GPU training job waits although the cluster has idle GPUs.', 'The job requests an unavailable GPU type plus an exclusive-node constraint in the selected partition.', ['Only jobs with the new constraint set remain Pending.', 'squeue reason reports ReqNodeNotAvail/Resources rather than generic capacity.', 'scontrol shows the GPU type/constraint combination matches no eligible node in that partition.', 'A corrected test request becomes eligible without changing cluster state.'], 'Correct the request or use the approved partition/capacity product.', 'Publish valid GRES/constraint combinations, validate submissions, and forecast topology-aware queue demand.'),
  make('bmc-unreachable-fw-update', 'BMC unreachable mid-firmware-update', 'A node\'s BMC stops responding to Redfish and IPMI midway through a scheduled firmware push, with no console access.', 'The BMC firmware update itself bricked the management controller\'s network stack before completing, leaving no out-of-band path at all.', ['Only the one node mid-update is affected; sibling nodes updated earlier in the batch are fine.', 'curl/redfishtool to the BMC times out; ipmitool lanplus also gets no response.', 'The Redfish TaskService resource last reported 62% complete before the listener stopped answering.', 'sol activate also fails, confirming the BMC service processor itself is unresponsive, not just the HTTPS listener.'], 'Escalate to vendor out-of-band recovery (BMC recovery jumper/USB-recovery image or RMA) rather than power-cycling blindly, since a forced power event mid-flash risks corrupting the recovery partition too.', 'Stage firmware updates one node at a time with a verified BMC recovery path documented per vendor before starting a batch, and never update BMC firmware unattended overnight.'),
  make('pxe-boot-after-rma', 'Node fails to PXE-boot after mainboard RMA', 'A returned-from-RMA GPU node with a new mainboard sits at "PXE-E51: No DHCP or proxyDHCP offers were received" and never enters the provisioning system\'s installing state.', 'The mainboard swap changed the node\'s MAC address, and the provisioning system\'s DHCP scope still has only the old MAC pre-registered, so no PXE-specific offer is returned.', ['Only the just-RMA\'d node fails; every other node in the same rack/VLAN PXE-boots normally.', 'tcpdump on the boot VLAN shows a DHCPDISCOVER from the new MAC with no DHCPOFFER in response.', 'The DHCP server\'s lease log and the provisioning system\'s MAC allowlist both show only the pre-RMA MAC address.', 'Registering the new MAC in the provisioning system produces an immediate DHCPOFFER and TFTP fetch on retry.'], 'Register the new MAC address in the provisioning system and DHCP scope, then retry the PXE boot.', 'Make MAC re-registration a mandatory step in the RMA/mainboard-swap runbook, verified via a boot-VLAN tcpdump check before the node is returned to service.'),
  make('bcm-category-drift', 'BCM node category push leaves one node with stale config', 'A category-wide configuration push to the gpu-a100 category completes on 29 of 30 nodes, but gpu-node-09 keeps its old kernel-module parameters because it was hand-edited outside the category months earlier.', 'A prior manual fix applied directly to the node (not through the category) created a persistent per-node override that the category push does not detect or reconcile.', ['Only gpu-node-09 diverges; all other members of gpu-a100 show the new parameters cleanly.', 'cmsh device list -c gpu-a100 shows gpu-node-09 as UP/HEALTHY, masking the config divergence entirely.', 'Diffing the category-rendered config against the node\'s actual /etc/modprobe.d file shows an extra hand-added parameter line absent from the category definition.', 'Reconciling the node-level override back into the category definition (or removing it) and reprovisioning brings the node in line with its 29 siblings.'], 'Reconcile the specific hand-edited file against the category\'s rendered config, then reprovision the node so category membership is authoritative again.', 'Treat any manual edit on a category-managed node as technical debt with a tracked follow-up to fold it into the category definition, and audit for node-level overrides on a recurring schedule.'),
  make('ansible-false-idempotent', 'Ansible playbook reports "changed" on every run', 'A templated DCGM exporter config playbook reports changed=1 on every node on every run, even against nodes nobody has touched since the last run.', 'The Jinja2 template renders a dict-derived YAML block whose key order is not guaranteed stable across runs, so the content-hash idempotency check sees a byte-level diff every time despite semantically identical output.', ['Every node shows changed=1 on every run, including nodes untouched for weeks.', '--check --diff shows the same metrics: block re-emitted with keys in a different order each render, same keys and values.', 'The underlying set_fact merges two group_vars dicts whose merge order depends on filesystem directory-listing order, which is not guaranteed sorted.', 'Sorting the dict with dict2items | sort(attribute=\'key\') before templating produces zero diff on three consecutive runs against an untouched node.'], 'Convert the source data to an explicitly sorted, ordered structure before templating so rendered output is byte-stable when nothing semantically changed.', 'Verify idempotency claims with three consecutive --check --diff runs showing zero diff, not merely a successful exit code, before trusting a playbook\'s changed= count.'),
  make('terraform-state-drift-destroy', 'terraform apply destroys a production resource due to state drift', 'An unrelated tag-only Terraform PR triggers an apply that unexpectedly destroys and recreates a production EBS volume holding checkpoint data.', 'A prior manual console resize of the volume during an incident was never reconciled back into the .tf source, and the resulting size/IOPS-ratio mismatch forces the provider to replace rather than update the resource.', ['The plan for an unrelated tag change shows -/+ on the volume resource, not the expected ~ in-place update.', 'terraform state show reveals state still records the pre-incident 300GiB size while the volume is actually 500GiB in reality.', 'git log on the .tf file shows no commit since well before the manual console resize two weeks earlier.', 'A corrected .tf declaration matching the real 500GiB size produces a clean ~ update with no replacement on a subsequent plan.'], 'Do not apply a plan showing an unexpected -/+ on a resource nobody intended to touch; update the .tf source to match reality first, then re-plan.', 'Require that any manual change to a Terraform-managed resource be followed immediately by a matching .tf update or an explicit terraform state operation, before the next unrelated apply can reach it.'),
  make('slurm-fairshare-starve', 'Slurm fairshare misconfiguration starves a research group\'s priority', 'Physics, climate, and astro jobs queue 10+ hours longer every day for three weeks, with no job outright failing and no single day looking anomalous.', 'A newly onboarded genomics account was given Fairshare=100 copy-pasted from an unrelated infrastructure-testing account, versus Fairshare=20 for the three established accounts, so the multifactor priority plugin favors genomics far out of proportion to its intended allocation.', ['squeue reason code for the affected accounts is (Priority), which reads as normal contention, not a policy bug.', 'sshare -l shows genomics FairShare near 1.0 versus roughly 0.2 for physics/climate/astro.', 'sacctmgr show assoc confirms RawShares of 100 for genomics against 20 for each of the other three accounts.', 'sacctmgr modify account genomics set fairshare=20 followed by a multi-day sshare check shows the ratios normalize as decayed usage history catches up.'], 'Correct the fairshare value to match the agreed proportional allocation, then confirm via sshare -l over several days as usage history decays toward the new weight.', 'Review any new association\'s fairshare value against the existing account tree before activation, and check sshare -l on a recurring cadence rather than only when a PI escalates.'),
  make('slurm-failover-lost-jobs', 'Slurm controller failover appears to lose running jobs', 'After the primary slurmctld fails and the backup takes over, squeue on the backup shows a nearly empty queue even though dozens of jobs were running moments earlier.', 'StateSaveLocation was configured to a path that resolves to local disk on the primary controller rather than genuinely shared storage reachable by both controllers, so the backup had no state to read on takeover.', ['Only failover events show job loss; day-to-day operation on the primary looked completely normal.', 'scontrol show config confirms StateSaveLocation is set, but the path is mounted as local disk on slurmctl-01 only.', 'journalctl -u slurmctld on the backup shows it started clean with an empty state directory rather than reading prior queue state.', 'sacct against slurmdbd still shows the accounting history intact, confirming the loss is queue-state-only, not a database failure.'], 'Fail back to the primary if it is recoverable to avoid further job loss, then remount StateSaveLocation on genuinely shared storage reachable by both controllers before the next failover test.', 'Test controller failover deliberately in a maintenance window, verifying the backup actually reads live queue state from StateSaveLocation, rather than assuming the config file entry alone guarantees shared-storage semantics.'),
  make('mpi-nccl-startup-hang', 'Multi-node MPI+NCCL training job hangs at startup', 'An 8-rank job across two nodes shows zero training progress; all ranks appear alive but nothing advances past process launch.', 'One node\'s MPI/PMIx rank bootstrap never completed because a firewalled out-of-band port prevented that node\'s ranks from being reachable, so the job never even reached the NCCL initialization the team assumed was hanging.', ['srun --overlap ps aux confirms all 8 rank processes exist and are running, ruling out a launch failure.', 'mpirun --report-bindings shows binding output for ranks 0-3 on node A but nothing at all for ranks 4-7 on node B.', 'PMIX_MCA_ptl_base_verbose=5 on node B shows repeated connection-refused attempts to node A\'s PMIx server port.', 'Opening the specific PMIx bootstrap port range between the two nodes produces complete bindings output for all 8 ranks and training proceeds to NCCL initialization.'], 'Open the required PMIx bootstrap port range between the affected nodes and relaunch; do not touch NCCL settings until MPI bootstrap is confirmed complete for every rank.', 'Validate PMIx/MPI bootstrap connectivity between all node pairs as part of node bring-up or firewall-change review, rather than defaulting straight to the NCCL/fabric layer on a startup hang.'),
  make('enroot-gpu-not-visible', 'Enroot/Pyxis job can\'t see the GPU the host can see', 'A researcher\'s srun --container-image job reports "no devices found" from nvidia-smi inside the container, while nvidia-smi on the bare host works fine.', 'The NVIDIA Container Toolkit hook that Enroot needs to bind-mount driver libraries and device files into the rootless filesystem is missing from /etc/enroot/hooks.d/ after a recent BCM image update.', ['Kubernetes-launched GPU Pods on the same node work fine, which initially misleads the on-call toward a driver theory.', 'nvidia-smi -L on the bare host lists all GPUs correctly, ruling out a driver/hardware fault.', 'ls -l /etc/enroot/hooks.d/*nvidia* returns no matching file on the affected node, unlike a known-good node in the same category.', 'Reinstalling the Enroot NVIDIA hook package and rerunning the job shows NVIDIA_VISIBLE_DEVICES populated inside the container and nvidia-smi succeeding.'], 'Reinstall or re-enable the Enroot NVIDIA hook package on the affected node and re-verify with a test container before returning it to the partition.', 'Include the Enroot NVIDIA hook file as an explicit item in the golden-image validation gate, since a working Kubernetes CDI GPU path on the same node proves nothing about Enroot\'s independent hook configuration.'),
  make('selinux-gpu-monitoring-block', 'SELinux enforcing mode silently blocks a GPU monitoring agent', 'The DCGM exporter starts, stays running, and shows no application-level error, but its GPU utilization metrics never populate on nodes that recently received a hardening baseline.', 'SELinux\'s targeted policy has no context mapping for a newer GPUDirect-adjacent device node the exporter needs to read, so enforcing mode silently denies the access without the exporter logging a permission error it can surface.', ['Only nodes that received the new hardening baseline this week are affected; older nodes with the same exporter version work fine.', 'The exporter process log shows no errors at all — it looks healthy from the application\'s own perspective.', 'ausearch -m avc -ts recent on the affected node shows repeated AVC denials against the exporter\'s domain for a specific device-node type.', 'audit2why decodes the denial as a missing type mapping for that device class, and a supplemental SELinux policy module resolves it without disabling enforcement.'], 'Install the correct supplemental SELinux policy module mapping the device-node type the exporter needs, rather than setting the node to permissive mode.', 'Include a policy-module validation step in the hardening-baseline canary gate specifically for any newly exposed GPU/monitoring device class, before the baseline ships fleet-wide.'),
  make('canary-firmware-not-representative', 'Coordinated rollout passes canary but breaks 20% of the fleet', 'A driver+CUDA+NCCL bump passes every canary gate cleanly, then hours into the second rollout wave, roughly a fifth of multi-node training jobs start failing with NCCL timeouts.', 'The canary\'s 8 nodes were all on one NIC firmware revision; the new NCCL version\'s updated transport-capability negotiation interacts badly with a different NIC firmware revision present on 20% of the fleet that the canary never included.', ['dcgm-diag, nccl-tests, and the training smoke job all passed cleanly on every canary node before rollout began.', 'Failures cluster precisely on nodes running one specific ConnectX-7 firmware revision, not randomly across the fleet.', 'The canary node inventory shows all 8 nodes on ConnectX-6 NICs at a single firmware revision, none matching the affected revision.', 'A second canary stratified by NIC model and firmware revision reproduces the timeout on a small controlled set before further rollout.'], 'Halt further rollout waves immediately, roll the affected batch back to the known-good combination, and re-stratify the canary by NIC model and firmware revision before resuming.', 'Make canary node selection an explicit, audited step stratified by NIC model, firmware revision, and GPU SKU, not just "grab idle nodes," before any coordinated change is allowed past the canary gate.'),
  make('cicd-emergency-override-bypass', 'CI/CD emergency override bypasses a destructive Terraform gate', 'A policy-check gate correctly blocks a Terraform plan that would destroy and recreate a production Lustre metadata server\'s storage volume, but the change lands anyway and the volume comes back empty.', 'An engineer used a documented but rarely-audited emergency-override flag to bypass the policy-check stage entirely under deadline pressure, applying the destructive plan directly without the missing change-ticket reference the gate was checking for.', ['conftest test tfplan.json shows a FAIL for the destroy action, confirming the gate worked correctly as designed.', 'The pipeline audit log shows the override flag was invoked immediately after the FAIL, with no incident ticket filed at the time.', 'terraform plan -refresh-only after the fact confirms the volume was recreated with a fresh empty ID, distinct from the original.', 'Recovery time from the empty volume exceeds what the original, properly-ticketed change would have taken end to end.'], 'Restore the metadata server from the most recent backup, then require a post-hoc mandatory incident ticket for the override use within one hour, reviewed on a dashboard.', 'Make the emergency-override path audited and rare rather than removing it: every use triggers an automatic follow-up PR that re-runs the full policy check against what was actually applied.'),
  make('kernel-patch-dkms-break', 'Routine kernel patch breaks the GPU driver DKMS build fleet-wide', 'A maintenance window applies routine kernel errata across the gpu-a100 fleet; after reboot, nvidia-smi fails on every node in the batch with a driver/library version mismatch, though nothing about the NVIDIA driver package changed.', 'The patch pipeline updated the kernel package but never triggered or waited for a DKMS rebuild of the nvidia kernel module against the new kernel headers before the nodes rebooted, so nvidia.ko no longer matches the running kernel.', ['Every node in the patched batch fails identically; nodes not yet in this maintenance wave are unaffected.', 'dmesg | grep -i nvidia shows "Failed to initialize NVML: Driver/library version mismatch" on every affected node.', 'dkms status shows the nvidia module still registered only against the previous kernel version, never rebuilt for the new one.', 'dkms autoinstall against the running kernel rebuilds the module successfully, and nvidia-smi returns clean without a further reboot.'], 'Run dkms autoinstall (or a targeted dkms install for the exact running kernel) to rebuild the module immediately, then verify with nvidia-smi before resuming any drained jobs.', 'Treat "kernel package update" and "DKMS rebuild and verify module load" as one atomic, gated maintenance step per node, never rebooting into a new kernel without a passing DKMS build gate for that exact kernel version.'),
  make('os-hardening-breaks-rdma', 'OS hardening baseline degrades RDMA performance via aggressive defaults', 'RDMA bandwidth on a newly-hardened node pool drops to a fraction of baseline immediately after a CIS-style hardening rollout, with no error reported by any application.', 'The hardening baseline tightened kernel sysctl defaults (rp_filter and socket buffer sizing) and applied a default-deny nftables posture without an explicit allow rule for the RoCE traffic class, throttling and partially dropping RDMA traffic instead of blocking it outright.', ['Only the newly-hardened node pool regresses; nodes pending the rollout still hit baseline RDMA bandwidth.', 'ib_write_bw on the hardened nodes returns roughly a third of the pre-hardening baseline bandwidth with no connection failure.', 'sysctl -a diffed against the pre-hardening baseline shows rp_filter and rmem/wmem defaults tightened beyond what RoCE traffic tolerates well.', 'ethtool -S on the NIC shows rising pause/drop counters correlated with the new nftables ruleset, and adding an explicit allow rule for the RoCE VLAN restores baseline bandwidth.'], 'Add an explicit allow rule for the RoCE/RDMA traffic class and relax the specific sysctl values shown to regress bandwidth, rather than exempting the node pool from hardening entirely.', 'Include an RDMA bandwidth check (ib_write_bw against a recorded baseline) in the hardening-baseline canary gate for any GPU/HPC node pool, since a generic CIS benchmark pass says nothing about fabric-specific performance regressions.'),
  make('dependency-cascade', 'Partial dependency failure causes a retry cascade', 'Checkout p99 latency rises from 400 ms to 18 seconds and error rate reaches 12%, although every service still has healthy replicas.', 'The inventory dependency became slow rather than unavailable; three caller layers each retry twice with longer timeouts than their callers, multiplying work until thread pools and queues saturate across the request path.', ['Impact begins with inventory-backed checkout operations in one region; read-only catalogue traffic remains healthy after an inventory database failover.', 'Traces show checkout -> pricing -> inventory, with repeated child spans for the same request and deadlines expiring at the outer service first.', 'Inventory latency is high but below its local timeout; caller concurrency, pending requests and retry attempts rise roughly sixfold while CPU remains moderate.', 'A canary with one bounded retry, jitter, propagated deadline and concurrency limit recovers p99 and stops amplification without changing inventory capacity.'], 'Disable nested retries at the outer layers, propagate a total deadline, cap concurrency and shed lower-priority work while the inventory owner restores latency.', 'Assign retry ownership to one layer, require timeouts to shrink down the call chain, instrument attempts versus logical requests, and load-test slow dependencies—not only hard failures.'),
  make('db-pool-exhaustion', 'Database connection pool exhaustion with a healthy database', 'API instances return connection-acquisition timeouts during peak traffic, while database CPU, memory and storage remain below 40%.', 'A new code path opens a transaction before a remote API call and holds the connection across that slow network wait, exhausting each application pool with idle-in-transaction sessions.', ['Only endpoints using the new enrichment call fail; the issue begins immediately after its deployment under peak concurrency.', 'Application metrics show pool active=max, pending acquire rising and query execution time normal for requests that obtain a connection.', 'pg_stat_activity shows many idle-in-transaction sessions from the new application version with ages matching the remote API latency.', 'Moving the remote call outside the transaction and canarying the change releases connections quickly; pool wait returns to baseline without increasing max connections.'], 'Roll back the code path or move the remote call outside the transaction; temporarily limit endpoint concurrency rather than increasing every pool.', 'Keep transactions narrow, set acquisition/statement/idle-transaction timeouts, expose pool wait and validate pool sizing against total database connection budget.'),
  make('lb-keepalive-502', 'Intermittent 502s from load balancer keep-alive mismatch', 'Clients see short bursts of 502 responses after quiet periods, but direct requests to all application instances succeed.', 'The load balancer reuses upstream connections longer than the application keep-alive timeout, occasionally sending a request on a socket the backend has already closed.', ['502s affect all routes at low steady traffic and spike just after idle periods; backend health checks stay green.', 'Load-balancer logs classify upstream reset before response; direct backend curl has no application error.', 'Packet timing shows the backend sends FIN at 60 seconds while the load balancer retains the connection for 75 seconds.', 'Setting the load-balancer upstream idle timeout below the backend keep-alive—or raising backend keep-alive above it—eliminates resets in a canary.'], 'Align timeouts so the outer proxy retires upstream connections before the backend and roll out the change gradually.', 'Maintain an end-to-end timeout budget covering client, CDN/LB, ingress/proxy and application; test connection reuse and idle-period behavior.'),
  make('nat-port-exhaustion', 'Cloud NAT port exhaustion causes intermittent outbound failures', 'Pods intermittently cannot call third-party APIs during batch peaks; DNS and internal traffic remain healthy and retries sometimes work.', 'Thousands of short-lived outbound connections share too few Cloud NAT source ports, amplified by disabled connection reuse and long TIME_WAIT retention.', ['Only internet egress from one subnet/NAT gateway fails during batch fan-out; private service calls are unaffected.', 'Applications report connect timeouts before TLS, while DNS answers and third-party status remain normal.', 'NAT metrics show allocated ports at limit and dropped connections; nodes show a large TIME_WAIT population to the same destinations.', 'Enabling connection pooling plus increasing/distributing NAT port capacity removes drops during a replayed peak.'], 'Throttle the batch, enable HTTP connection reuse and add bounded NAT port capacity; avoid retrying connect failures without jitter.', 'Capacity-model source ports, alert on allocation/drop metrics, reuse connections, distribute egress failure domains and load-test peak fan-out.'),
  make('cache-stampede', 'Expired hot key creates a cache stampede', 'A product page becomes slow every 15 minutes; Redis CPU is moderate but the database sees a sudden 40x query burst.', 'Thousands of replicas observe the same hot key expiring simultaneously and all regenerate it from the database because there is no single-flight lock, TTL jitter or stale-serving path.', ['The latency spike repeats at the hot key TTL boundary and affects one high-traffic product family.', 'Application traces show cache misses followed by identical database queries; scaling replicas makes the burst larger.', 'Redis shows a sharp miss spike without eviction or memory pressure; the database query fingerprint matches the key regeneration.', 'A canary using per-key single-flight, TTL jitter and stale-while-revalidate keeps database traffic bounded through expiry.'], 'Rate-limit regeneration and serve a safe stale value while one worker refreshes the hot key.', 'Use single-flight/request coalescing, TTL jitter, negative caching where safe, stale-serving policy and origin-capacity guardrails.'),
  make('kafka-lag-hot-partition', 'Kafka consumer lag grows on one hot partition', 'Total consumer-group lag rises continuously although consumer CPU is low and adding replicas does not improve throughput.', 'The message key sends most records to one partition; Kafka allows only one active consumer per partition, so extra consumers remain idle while the hot partition serializes work.', ['Lag is isolated to one topic and primarily one partition following a new high-volume tenant launch.', 'Consumer-group output shows one partition with millions of records lag while several consumers have no assignment.', 'Broker/ISR health is normal; per-key sampling shows the tenant ID dominates the hot partition and processing time per record is stable.', 'A controlled producer change to a higher-cardinality stable key distributes new traffic and lag growth stops; old lag drains through the original partition.'], 'Throttle the dominant producer if needed and scale processing only after fixing partition/key distribution; preserve ordering requirements.', 'Capacity-test key cardinality, monitor lag/throughput per partition, define repartition migration and make consumers idempotent for replay.'),
  make('disk-inode-exhaustion', 'Disk has free space but writes fail with ENOSPC', 'A logging sidecar and application fail to create files even though df -h reports 48% free space.', 'Millions of tiny rotated files consumed every inode on the filesystem; byte capacity remained available, so space-only alerts never fired.', ['Only nodes running a newly changed debug-log rotation policy fail after several days; other nodes have the same byte utilization.', 'Application and sidecar logs show ENOSPC on create; Kubernetes reports no DiskPressure because byte thresholds are not crossed yet.', 'df -i reports 100% inode use and find/count identifies tiny files under one debug-log directory.', 'Stopping the producer and deleting only expired files through the approved retention path restores file creation; inode use falls immediately.'], 'Stop the runaway file producer, preserve representative evidence and remove only confirmed expired files; cordon nodes if runtime writes are at risk.', 'Alert on inode as well as byte usage, cap file count/retention, prefer aggregated logs and validate rotation under sustained debug volume.'),
  make('clock-skew-oidc', 'OIDC authentication fails on one node due to clock skew', 'Users receive intermittent “token used before issued” and “token expired” errors only when requests land on one application instance.', 'That node lost its chrony source after a firewall change and drifted seven minutes, causing local JWT nbf/iat/exp validation to reject otherwise valid tokens.', ['Authentication failures follow one node across users and tokens; other replicas accept the same token.', 'Application logs contain nbf/iat/exp validation errors, while issuer discovery, JWKS retrieval and signatures succeed.', 'timedatectl/chronyc show the node is unsynchronized and seven minutes ahead; NTP traffic is denied in the new host firewall rules.', 'Restoring the approved time source and safely stepping/slewing the node while drained makes token validation succeed.'], 'Drain the skewed node, restore time synchronization through the approved source and re-admit only after offset is within policy.', 'Monitor clock offset/synchronization, include NTP in firewall conformance tests and treat time as a security/control-plane dependency.'),
  make('deployment-schema-rollback', 'Application rollback fails after an incompatible database migration', 'A release increases errors, but rolling application Pods back makes failures worse because the previous version cannot read the new schema.', 'The deployment performed a destructive rename in the same release as the code change, violating expand/contract compatibility; rollback restored old code but not the old column contract.', ['Impact begins after a release containing both binary and migration changes; all instances and regions using the database are affected.', 'The new version shows one logic regression; the rolled-back version reports missing-column errors immediately.', 'Migration history shows old_column renamed to new_column with no compatibility view/dual-write; database health itself is normal.', 'A forward-compatible hotfix that reads the new schema restores service; a later staged contract migration removes the old path safely.'], 'Stop further rollback, deploy the smallest forward fix compatible with the current schema and protect writes while consistency is validated.', 'Use expand/migrate/contract phases, backward-compatible migrations, dual-read/write where required, versioned contracts and rollback rehearsals.'),
  make('cicd-runner-starvation', 'Shared CI runner pool starves production hotfixes', 'A critical hotfix waits 48 minutes for a runner while hundreds of low-priority nightly jobs occupy the entire pool.', 'One undifferentiated autoscaling runner queue has no priority/reservation; slow scale-out plus a cloud quota ceiling lets batch work consume every execution slot.', ['All projects using the shared pool queue after nightly fan-out; externally hosted checks are unaffected.', 'Queue time dominates job duration; hotfix jobs have no priority class and runner utilization is 100%.', 'Autoscaler requests more instances but the cloud API rejects them at the regional vCPU quota; many long batch jobs are non-preemptible.', 'A reserved protected runner pool executes the hotfix immediately, and admission limits keep nightly fan-out within remaining capacity.'], 'Route the hotfix through a pre-approved protected runner pool and throttle non-critical batch jobs; do not cancel arbitrary in-flight releases.', 'Separate protected and batch capacity, enforce fair-use/concurrency limits, alert on queue SLO and quotas, and test runner scale-out during peak fan-out.'),
  make('gitops-mutating-webhook-loop', 'GitOps controller endlessly reverts a mutating webhook field', 'Argo CD/Flux reports permanent drift and continuously patches a Deployment although no engineer is changing Git.', 'A mutating admission webhook injects a changing timestamp annotation after every update; the GitOps controller owns/compares the field and its correction triggers reinjection.', ['Only workloads handled by the new webhook flap; Git revision remains unchanged and application replicas stay mostly available.', 'Controller diff shows one generated annotation changing; audit logs alternate GitOps patch and webhook mutation.', 'Server-side dry-run reproduces the injected timestamp on every request, proving the desired object can never equal observed state.', 'Removing the volatile mutation or configuring a narrowly scoped ignore for a non-semantic field stops reconciliation without disabling GitOps.'], 'Pause reconciliation only for the affected application if patch churn threatens the API; remove the non-deterministic mutation or ignore that exact safe field.', 'Make admission mutation deterministic, define field ownership, test desired-versus-admitted manifests in CI and alert on sustained reconciliation rate.'),
  make('terraform-lock-orphan', 'Terraform state lock remains after a cancelled pipeline', 'Every deployment reports “Error acquiring the state lock” after yesterday’s pipeline was cancelled.', 'The CI job was force-terminated after acquiring the remote backend lock, leaving a stale lock record even though no Terraform process or apply remains active.', ['Only one workspace/backend is blocked; cloud resources and other workspaces are healthy.', 'The error includes a lock ID, owner and creation time matching the cancelled pipeline.', 'CI runner/process inventory and cloud audit logs show no surviving apply; remote state serial has not changed since the last successful run.', 'Using force-unlock with the verified lock ID, followed by refresh-only plan, clears the block without state mutation.'], 'Prove no live owner exists, record the lock metadata, then force-unlock that exact ID and run a refresh-only/normal plan before any apply.', 'Use graceful job cancellation, bounded apply timeouts, lock-owner observability and a reviewed stale-lock runbook—never automated age-only force unlock.'),
  make('noisy-neighbor-steal', 'VM latency regression caused by CPU steal time', 'One VM has high request latency despite low process CPU, normal application queues and no recent deployment.', 'The hypervisor host is overcommitted or contended; the guest spends substantial time in CPU steal, invisible when looking only at process utilization.', ['Only several VMs on one placement host regress; bare-metal and other-zone instances are unaffected.', 'Application latency rises with low in-guest CPU and no database/network wait; autoscaling adds similarly affected VMs in the same host group.', 'vmstat/top show sustained steal time above 20%; scheduler run queues grow even though guest CPU accounting looks moderate.', 'Moving one canary VM to a different host/placement group restores latency with identical image and load.'], 'Migrate or replace affected instances through a controlled rollout and work with the infrastructure provider on the contended host.', 'Monitor steal time, diversify placement/failure domains, benchmark instance families and include provider-host contention in the latency playbook.'),
  make('message-duplicate-processing', 'At-least-once delivery creates duplicate customer actions', 'A queue consumer charges a small set of orders twice after broker connectivity instability, even though each message ID was unique at publish time.', 'The consumer performs the external charge before committing the queue offset; a crash between those actions causes redelivery and the handler has no durable idempotency record keyed by the business operation.', ['Duplicates correlate with consumer restarts and rebalance events; producer publish count remains one per order.', 'Tracing shows the same message/order handled twice by different consumer instances with the first attempt ending before commit.', 'Payment provider logs contain two requests with different generated idempotency keys; broker offsets confirm redelivery as designed.', 'A canary using the stable order ID as provider idempotency key plus a durable processed-event record accepts redelivery without a second charge.'], 'Stop or throttle the affected consumer, reconcile duplicate actions through the business-approved process and deploy idempotent handling before replay.', 'Design for at-least-once delivery, use stable business idempotency keys, transactional outbox/inbox where appropriate, and test crash points between side effect and acknowledgement.'),
  make('backup-restore-corrupt', 'Backups succeed nightly but restore validation fails', 'The backup dashboard is green for 90 days, but a disaster-recovery drill cannot start the restored database.', 'The backup job uploaded base files but silently omitted required WAL/archive segments after a credential rotation; job success measured upload completion, not a consistent recoverable restore point.', ['Production is healthy; failure is discovered only in the isolated DR drill after selecting the newest “successful” backup.', 'Backup logs report uploaded bytes and exit 0, but the restore tool asks for a missing WAL segment during recovery.', 'Object storage audit shows WAL uploads stopped immediately after archive-credential rotation while base-backup uploads continued under a different credential.', 'Restoring the newest backup before the credential change succeeds; fixing archive credentials plus a new backup passes point-in-time recovery and consistency checks.'], 'Protect production, select the newest independently validated recoverable restore point and communicate the actual RPO gap before recovery.', 'Define backup success as automated isolated restore plus integrity/application checks, monitor archive continuity, rotate credentials with end-to-end validation and report tested RPO/RTO.'),
  make('lustre-mds-metadata-bottleneck', 'Lustre MDS metadata bottleneck under checkpoint load', 'A large training job\'s periodic checkpoint writes make cluster-wide Lustre feel unusably slow, even though OST throughput graphs never approach saturation.', 'The checkpoint-sharding pattern creates tens of thousands of small files and directory entries per checkpoint, saturating MDS metadata operations (open/create/unlink) rather than OST bandwidth; the filesystem is metadata-bound, not throughput-bound.', ['Stalls begin only during checkpoint windows and affect every job on the filesystem, not just the training job; OST write bandwidth graphs stay under 40% of rated throughput throughout.', 'lfs df -h shows capacity and bandwidth headroom on every OST; ls -l on the checkpoint directory takes 8-12 seconds to return for a directory with 240,000 entries.', 'lctl get_param mdt.*.md_stats on the MDS shows open/create/unlink rates 15x baseline during the checkpoint window, and mdt.*.exports shows RPC queue depth backed up on the metadata service.', 'Switching the checkpoint writer to shard into fewer, larger files per node instead of per-rank-per-tensor cuts create/unlink RPCs by roughly 90%, and the cluster-wide stall does not recur on the next checkpoint.'], 'Throttle or pause concurrent checkpoint writers immediately and, if available, move hot metadata onto a faster MDT/DNE target; do not add OSTs or OST bandwidth, since that does not address a metadata-bound bottleneck.', 'Design checkpoint sharding around file count as a first-class constraint, use DNE or a striped metadata target for high-file-count directories, and alert on MDS RPC/metadata-op rate separately from OST bandwidth. See Volume 6, Chapter 6 for the metadata-versus-throughput distinction behind this and how Lustre, GPFS and ZFS each fail differently.'),
  make('gpfs-quorum-loss-rolling-upgrade', 'GPFS quorum loss during a rolling storage-node upgrade', 'Taking one GPFS/Spectrum Scale storage node down for a routine patch during a rolling maintenance window causes filesystem access to stall cluster-wide, not just on the node being upgraded.', 'The cluster\'s quorum node set had only the minimum required quorum nodes configured with no spare margin; taking one quorum node offline for maintenance dropped the surviving set below the quorum threshold, forcing the file system into a cluster-wide unavailable state until quorum was restored.', ['Every client across the cluster reports filesystem access hangs within seconds of the maintenance node going offline, not only jobs using that specific storage node.', 'mmgetstate -a shows the cluster in state "arbitrating" on the majority of nodes, and the maintenance node shows "down".', 'mmlsmgr shows no elected file system manager; mmdiag --network shows the surviving quorum nodes unable to re-elect because the quorum node count (2 of 3 configured) is below the minimum majority.', 'Restoring the maintenance node to the network restores quorum, and mmgetstate -a returns "active" cluster-wide within under a minute, confirming the stall was quorum arithmetic, not a local disk or network fault.'], 'Bring the maintenance node back online (or promote a standby quorum node) immediately to restore majority quorum; do not attempt to force cluster state or restart file-system managers while below quorum.', 'Configure an odd number of quorum nodes with at least one spare above the bare minimum (e.g. 5 to tolerate one planned plus one unplanned loss), and require change management to verify remaining quorum count before any storage-node maintenance window. See Volume 6, Chapter 6 for why GPFS\'s distributed quorum-based coordination fails differently from Lustre\'s dedicated-MDS model.'),
  make('xfs-inode-exhaustion-checkpoint-shard', 'XFS inode exhaustion from checkpoint sharding', 'A training job\'s checkpoint writes start failing with "No space left on device" on an XFS-backed local scratch volume that df -h reports as only 31% full.', 'The checkpoint-sharding scheme writes one small file per rank/tensor-shard pair per step, and across days of checkpoints this created millions of small files that exhausted the fixed inode allocation XFS reserved at format time, while byte capacity remained available.', ['Failures begin only on nodes running the newer checkpoint-sharding code path; nodes still on the older single-file-per-rank format are unaffected at the same byte utilization.', 'df -h /mnt/scratch reports 31% used; the checkpoint write fails immediately with ENOSPC on file create, not on write.', 'df -i /mnt/scratch reports 100% inode use (16777216/16777216); xfs_db -c "sb 0" -c "print icount ifree" -r /dev/nvme0n1 confirms allocated inode count has reached the filesystem maximum.', 'Deleting three days of superseded checkpoint shards frees several million inodes immediately and new checkpoint writes succeed; reformatting a test volume with a higher inode density (mkfs.xfs -i size=256) avoids recurrence at the same file count.'], 'Delete only confirmed superseded/expired checkpoint shards through the approved retention process to free inodes immediately; do not delete active or unverified checkpoints, and do not resize the filesystem live.', 'Shard checkpoints into fewer, larger files per node instead of per-rank-per-tensor, alert on inode utilization independently of byte utilization, and set XFS imaxpct/inode size appropriately at format time for workloads known to produce many small files. See Volume 1, Chapter 3 for the inode-versus-byte-capacity distinction this incident depends on.'),
  make('grafana-stale-healthy-dashboard', 'Grafana dashboard shows healthy while the underlying Prometheus data is stale', 'A GPU fleet dashboard shows all panels green with plausible-looking utilization values, but on-call later discovers the cluster has been unreachable for six hours.', 'Prometheus stopped successfully scraping the affected job after a service-discovery relabel change, but Grafana rendered the last successfully-scraped value across the panel\'s time window, and thresholds were set on the value rather than on data freshness, so a stale last-known value looked like a healthy plateau.', ['The dashboard panel value has not changed at all in six hours, but nothing about its color or threshold state changed either, because thresholds evaluate the value, not its freshness.', 'Grafana Explore on the same panel\'s query, when the time range is narrowed to the last 10 minutes, returns no data points at all rather than a flat line.', 'Prometheus /api/v1/targets shows the job in health "down" with lastScrape six hours in the past; up{job="..."} returns 0 for the affected target for the entire window.', 'Adding an explicit staleness/absent() alert and a "last scrape age" panel immediately flags the gap on a canary dashboard, and restoring the relabel config resumes fresh scrapes with up returning to 1.'], 'Treat a target reporting up=0 or a stale lastScrape timestamp as an active outage regardless of what the last rendered value shows; fix the scrape/service-discovery configuration rather than refreshing the dashboard.', 'Add explicit staleness alerts (absent_over_time, sample-age checks) on critical panels, avoid dashboard designs that render only the last value without a freshness indicator, and treat "up" as a first-class panel.'),
  make('loki-label-cardinality-collapse', 'Loki label cardinality collapse under high-volume GPU node logs', 'After onboarding verbose per-request GPU job logs, Loki ingestion latency spikes, queries start timing out, and the ingesters begin OOMing.', 'A new log pipeline stage added request_id (and, on some lines, a pod-unique job_id) as a Loki label rather than as log-line content, creating one stream per request instead of per pod; Loki\'s index is built on the label set, so this produced millions of near-single-entry streams and overwhelmed the ingester index and chunk store.', ['Ingestion and query problems begin immediately after a log-pipeline release that added new labels; log volume in bytes/sec is only modestly higher than before.', 'logcli series --analyze-labels {job="gpu-training"} shows request_id and job_id among the label set with tens of thousands of distinct values each.', 'Loki ingester metrics show loki_ingester_memory_streams and loki_ingester_streams_created_total climbing continuously without bound, and ingester pods are OOMKilled repeatedly.', 'Reconfiguring the pipeline to keep request_id and job_id as structured log-line fields instead of labels, then restarting ingestion, drops loki_ingester_memory_streams by two orders of magnitude and query latency returns to baseline.'], 'Roll back or patch the log pipeline to stop promoting per-request/per-job unique fields to labels immediately; do not scale ingesters to absorb the stream count, since the label design itself is unbounded.', 'Enforce a label budget for Loki similar to Prometheus label discipline, use structured logging fields or LogQL line filters for high-cardinality identifiers, and alert on stream count growth per tenant/job.'),
  make('network-operator-nic-firmware-drift', 'NVIDIA Network Operator fails to reconcile after a NIC firmware change', 'After an out-of-band NIC firmware update on a subset of GPU nodes, the NVIDIA Network Operator\'s NicClusterPolicy shows persistent "not ready" state and MOFED/RDMA pods on those nodes keep restarting.', 'The out-of-band firmware update changed the NIC\'s persisted mlxconfig parameters without going through the operator\'s expected upgrade path, so the operator\'s MOFED driver container detects a mismatch between the NicClusterPolicy\'s declared firmware baseline and the card\'s actual state and refuses to mark the node ready.', ['Only the nodes that received the manual out-of-band firmware push show the operator drift; sibling nodes on the previous firmware and the standard operator-managed upgrade path remain Ready.', 'kubectl get pods -n nvidia-network-operator -o wide shows the mofed-driver pod on the affected nodes in CrashLoopBackOff, while the same pod on unaffected nodes is Running.', 'kubectl logs -n nvidia-network-operator -l app=mofed-driver on the affected node shows a firmware-version mismatch error against the version pinned in the NicClusterPolicy spec, and mlxfwmanager -q on the host shows a different PSID/firmware version than the operator expects.', 'Updating the NicClusterPolicy CR\'s pinned firmware/driver version to match the newly-applied firmware (or reverting the NIC firmware to the operator-managed baseline with mlxfwmanager) and forcing reconciliation clears CrashLoopBackOff and the node returns to Ready.'], 'Do not delete/recreate the NicClusterPolicy or force-restart the operator broadly; reconcile the single source of truth by rolling the out-of-band firmware back or updating the CR to match it, on the specific affected nodes only.', 'Route all NIC firmware changes through the Network Operator\'s managed upgrade path instead of out-of-band vendor tools, and add a drift-detection check comparing mlxfwmanager-reported firmware against the operator\'s expected baseline.'),
  make('ib-subnet-manager-failover', 'InfiniBand subnet manager failover loses fabric routing state', 'A brief, fabric-wide wave of RDMA connection errors and NCCL timeouts hits many unrelated jobs simultaneously for about a minute, then resolves on its own.', 'The primary OpenSM subnet manager instance missed its health-check heartbeat and a standby SM took over mastership; the new master recomputed and reprogrammed switch forwarding tables and LIDs from scratch instead of preserving the prior routing assignment, causing a brief fabric-wide routing reset rather than a localized failure.', ['The error wave hits jobs across many independent racks/partitions at nearly the same timestamp, ruling out a single node or single link failure.', 'ibstat/ibstatus on affected hosts briefly show port state transitioning and returning to Active, without any physical link (cable/optics) event logged.', 'sminfo on the fabric shows the SM master GUID changed at the exact incident timestamp; the opensm log on the new master shows "SUBNET UP" reinitialization with LID reassignment following a master takeover, and the previous master\'s log shows repeated missed heartbeats before going into standby.', 'A controlled SM failover test in a subsequent maintenance window reproduces the same brief reroute; adjusting SM keepalive/polling thresholds so a transient missed heartbeat does not trigger failover eliminates the false trigger in the retest.'], 'Do not intervene on individual jobs or nodes during the event; confirm via sminfo/opensm logs that this is an SM mastership failover and let the new master complete re-routing, then investigate why the primary SM missed its heartbeat.', 'Tune subnet-manager heartbeat/polling and failover thresholds to tolerate brief primary SM hiccups without triggering a full re-route, keep SM priority/standby configuration under change control, and alert on SM master GUID changes as a first-class fabric event.'),
  make('bonded-nic-silent-half-bandwidth', 'Bonded NIC interface silently drops to half bandwidth after a driver update', 'A node\'s bonded network interface reports "up" with LACP negotiated, but sustained throughput tests show roughly half of the expected bandwidth, unnoticed until a large data-transfer job ran slow.', 'A NIC driver update left one of the two physical members of the LACP bond in a degraded link-training state, negotiated at half the expected speed instead of failing the link entirely, so the bond driver continued treating both members as active and load-balancing across them, silently halving effective aggregate throughput instead of failing over.', ['Only nodes that received the specific NIC driver update in the last maintenance window show the slowdown; the same bond configuration on nodes with the previous driver version is unaffected.', 'cat /proc/net/bonding/bond0 shows both slaves listed as "MII Status: up", with "Speed: 10000 Mbps" for one and only "Speed: 5000 Mbps" for the other, despite the bond\'s configured mode assuming symmetric member speed.', 'ethtool eth1 on the degraded member reports "Speed: 5000Mb/s" versus ethtool eth0 reporting "Speed: 10000Mb/s"; dmesg on the affected node shows a link-training renegotiation message at the time the driver update took effect, with no link-down event.', 'iperf3 to the node measures roughly half of the two-node baseline bandwidth; forcing eth1 to renegotiate (ethtool -s eth1 autoneg off then on, or a physical reseat) restores it to 10000 Mbps and iperf3 throughput returns to baseline.'], 'Identify and isolate the degraded bond member; do not just restart the bond or reboot blindly. Force a renegotiation or physically reseat/replace the affected link, removing it from the active set if it cannot be restored immediately.', 'Alert on per-member bond interface speed/duplex mismatch (not just carrier/up state), include post-driver-update link-speed verification in the maintenance checklist, and monitor bond throughput against an expected baseline rather than relying on LACP "up" status alone.'),
  make('conntrack-table-full-kernel-update', 'A routine kernel update changes default netfilter conntrack limits, causing connection drops under load', 'After a routine kernel/OS patch, a previously stable service starts dropping a small percentage of new connections under normal peak load, with no application or network change.', 'The kernel update shipped a new default for net.netfilter.nf_conntrack_max (or the distro\'s sysctl-defaults package reset a previously-tuned override back to the kernel default) far lower than the connection concurrency the service actually needs at peak; the conntrack table fills and the kernel drops new connections rather than tracking them.', ['The drop rate correlates exactly with the maintenance window of the kernel/OS patch rollout, not with any application deploy or traffic-pattern change; only patched nodes are affected at the same load level.', 'Application logs show new inbound connections failing to establish, not timing out mid-request; no corresponding error appears server-side in the application itself.', 'sysctl net.netfilter.nf_conntrack_count is at or above sysctl net.netfilter.nf_conntrack_max at the moment of drops, and dmesg shows repeated "nf_conntrack: table full, dropping packet" entries; conntrack -L | wc -l confirms the table is saturated.', 'Raising net.netfilter.nf_conntrack_max back to the previously-tuned value (and persisting it in the sysctl config that survives the next update) immediately stops the "table full" messages, and drops disappear under the same replayed load.'], 'Raise net.netfilter.nf_conntrack_max (and nf_conntrack_buckets proportionally) back to the previously validated value immediately; do not disable connection tracking or the firewall entirely to work around the symptom.', 'Pin conntrack sysctl overrides in a config-management layer that reasserts them after every kernel/OS update, add a fleet-wide check that diffs sysctl defaults after patch rollout, and alert on nf_conntrack_count as a percentage of nf_conntrack_max well before it reaches capacity.'),
  make('systemd-gpu-service-race-boot-order', 'systemd unit ordering causes a GPU-dependent service to start before the driver is loaded', 'After a routine reboot, a node\'s GPU health-check/monitoring agent service is permanently in a failed state, although the GPU driver and nvidia-smi work fine once someone logs in and restarts the service manually.', 'The monitoring agent\'s systemd unit had no After=/Requires= dependency on the NVIDIA driver-loading service, so at boot it started and called nvidia-smi before the kernel module finished loading, failed immediately, and systemd\'s restart policy let it exhaust its retry budget and land in "failed" permanently rather than retrying once the driver became available.', ['Only reboots reproduce the failure; the same node is healthy indefinitely once someone manually restarts the service, and other nodes with slightly slower boot timing sometimes boot healthy by chance.', 'systemctl status gpu-health-agent shows "Active: failed (Result: exit-code)" with a start timestamp only a few seconds after boot; the unit\'s StartLimitBurst has been exhausted so systemd will not retry it further.', 'journalctl -u gpu-health-agent -b shows the process exiting with a CUDA/NVML initialization error, timestamped before journalctl -u nvidia-persistenced -b shows the driver-side service reporting ready.', 'systemd-analyze critical-chain gpu-health-agent.service confirms the unit has no After= dependency on nvidia-persistenced.service; adding After=/Requires= on that service plus a bounded Restart=on-failure makes the unit start only after the driver is confirmed loaded, and it comes up healthy on the next several reboots.'], 'Manually restart the failed service now (systemctl reset-failed && systemctl restart gpu-health-agent) to restore monitoring immediately, then fix the ordering so it survives the next reboot.', 'Add explicit After=/Requires= dependencies from every GPU-dependent unit onto the driver-load service/target, use a bounded Restart=on-failure with RestartSec instead of relying on first-boot timing luck, and add a post-reboot health check that catches "failed" units before assuming a clean boot.'),
  make('slurm-healthcheck-venv-false-green', 'A Slurm health-check script\'s own dependency (a Python venv) silently breaks, so every node passes health checks while actually degraded', 'Slurm\'s node health check (NHC-style script) reports every node healthy fleet-wide, but users are hitting GPU and fabric failures the health check should have caught and drained the node for.', 'An unrelated fleet-wide Python package update, pushed through the same config-management channel used for the health-check\'s virtualenv, broke an import inside the health-check script\'s venv; the wrapper treats any exception during health evaluation as "no problems found" and exits 0, so the health check has been silently doing nothing meaningful while still reporting success.', ['GPU/fabric failures reported by users do not correlate with any node health check ever marking a node down or drained in the same window; sinfo shows all nodes in state "idle"/"alloc", never "drain" or "down", throughout the incident.', 'scontrol show node <node> shows Reason= empty and the node\'s health-check-related state unchanged for weeks, despite dcgm-diag run manually on the same node reporting active Xid errors.', 'Running the health-check script\'s Python entrypoint directly, outside the Slurm-wrapped cron/prolog path, shows a traceback: ModuleNotFoundError for a dependency the venv used to have, and the wrapper script\'s exit code is 0 despite the traceback because it catches all exceptions and treats them as "healthy."', 'Rebuilding the health-check venv from the pinned requirements file (pip check; pip install -r requirements.txt --force-reinstall) removes the traceback, and rerunning the script correctly detects the same injected Xid condition and drains the node as designed.'], 'Rebuild/repair the health-check script\'s Python environment on affected nodes immediately, and manually run dcgm-diag/fabric checks fleet-wide to find nodes the broken health check missed while it was silently failing.', 'Make the health-check wrapper fail closed (any internal exception should drain the node or alert, never exit 0), pin and isolate the health-check script\'s own dependencies from general fleet package updates, and add a synthetic-failure test that periodically injects a known-bad condition to confirm the health check still catches it.'),
  make('dcgm-scrape-target-down-masked-by-average', 'A DCGM Exporter Prometheus scrape target is silently up=0 for one node, and no one notices because the fleet-wide dashboard only shows averages', 'GPU utilization on the fleet-wide Grafana dashboard looks normal, but one specific node has actually had no real telemetry for hours because its DCGM Exporter scrape target is unreachable, not because the GPU is idle.', 'A node-local network/pod restart left that node\'s dcgm-exporter Prometheus scrape target in state up=0, but the fleet dashboard\'s panel aggregates avg(DCGM_FI_DEV_GPU_UTIL) across all nodes, so one dead target among dozens simply drops out of the average instead of visibly showing a gap, and DCGM/the exporter process itself is perfectly healthy and would report correctly if actually scraped.', ['The fleet-wide average utilization panel shows no anomaly at all across the incident window; only a per-node breakdown reveals one node missing entirely rather than at zero.', 'nvidia-smi and dcgm-diag run directly on the affected node show the GPUs healthy and under active workload the whole time, ruling out an exporter or GPU-health problem.', 'Prometheus /api/v1/targets shows the dcgm-exporter target for that node in health "down" with a lastScrape timestamp four hours in the past, while up{job="dcgm-exporter"} for that instance returns 0; every other instance in the same job returns 1.', 'Restarting the exporter pod/service on the affected node restores the scrape target to health "up" and count(up{job="dcgm-exporter"}==0) drops from 1 to 0; adding a per-target absent/staleness alert instead of only an averaged panel catches the same condition immediately on a subsequent induced test.'], 'Restart or repair the specific node\'s dcgm-exporter/scrape path and confirm the target returns to up=1; do not treat the fleet average as evidence the fleet is fully instrumented.', 'Alert on count(up{job="dcgm-exporter"}==0) or per-target absence rather than only fleet-wide averages, add a per-node target-health panel alongside any aggregated utilization panel, and treat a missing series as unknown, never as zero utilization.'),
  make('zfs-arc-undersized-checkpoint-cache-thrash', 'A ZFS-backed local NVMe checkpoint-staging tier gets slower every week even though nothing about the hardware changed', 'A node-local ZFS pool used as the fast checkpoint-staging tier (the local-NVMe hop ahead of the shared parallel filesystem) shows steadily rising write latency over weeks, and the team\'s first instinct is to suspect the NVMe device is wearing out.', 'The ZFS ARC (Adaptive Replacement Cache) was left at its default size on a node that also runs memory-hungry data-loader workers; as those workers\' memory footprint grew over successive job configs, the ARC was repeatedly evicted under memory pressure, so an increasing share of checkpoint-staging reads and writes fell through to physical NVMe instead of being absorbed by cache — which looks identical to "the disk is degrading" if you only watch latency, not cache-hit ratio.', ['smartctl and NVMe wear-leveling counters show the device at 4% wear after 14 months — nowhere near end-of-life, ruling out the hardware-degradation theory the team started with.', 'zpool status -v shows the pool ONLINE with zero read/write/checksum errors on every vdev, and zpool iostat -v shows latency elevated uniformly across all vdevs in the pool, not concentrated on one device the way a failing drive would show.', 'arc_summary shows ARC size sitting well below c_max and a hit ratio that has dropped from roughly 92% six months ago to 61% now, tracking almost exactly with the memory footprint growth of a co-located data-loader workload added over the same period.', 'Setting a floor on ARC size (or moving the memory-hungry data-loader workers to a different node) restores the hit ratio to its earlier level within one cache-warm cycle, and write latency returns to baseline without touching the NVMe device at all.'], 'Set a minimum ARC size (zfs_arc_min) so a co-located memory-hungry workload cannot starve the cache to near zero, and confirm the fix by watching hit ratio recover, not just latency.', 'Track ARC hit ratio as a first-class metric alongside device latency for any ZFS-backed cache tier, and treat "latency is rising" as a question with at least two live hypotheses (device degradation vs. cache starvation) until the ARC/vdev evidence separates them. See Volume 6, Chapter 6 for why this local ZFS tier exists at all in the checkpoint-staging path.'),
  make('cgroup-namespace-leak-zombie-pod-resources', 'A node\'s allocatable memory and PID count silently shrink over weeks even though kubectl shows a completely healthy set of running Pods', 'A GPU node that has been up for several weeks reports steadily less allocatable memory and available PIDs than its Pod count should account for, and every Pod Kubernetes currently reports as Running looks completely healthy.', 'A container runtime bug/race under specific restart timing left several old Pods\' cgroups and PID/mount namespaces behind after the Pods themselves were deleted from the Kubernetes API — the kernel-level cgroup hierarchy and its accounted memory/PIDs were never torn down even though nothing about them is visible to kubectl, since kubectl only reflects API object state, not actual kernel-resource state on the node.', ['kubectl get pods on the node shows only the expected, currently-scheduled Pods — nothing in the Kubernetes API hints anything is wrong, which is exactly why this incident survives so long before anyone notices.', 'node allocatable memory reported by kubectl describe node has drifted down over weeks relative to the sum of currently-scheduled Pods\' requests, with no corresponding increase in actual workload.', 'ls /sys/fs/cgroup/kubepods.slice/ (or the runtime-specific cgroup path) shows several cgroup directories whose pod-UID does not match any Pod currently returned by kubectl get pods -A, and ps -eLf --forest run against the PIDs still resident in those directories shows live kernel processes with no corresponding container in crictl ps.', 'Manually tearing down the confirmed-orphaned cgroup/namespace set (after verifying via crictl/runtime state, not guesswork) returns allocatable memory and PID headroom to the expected value immediately, and the drift does not resume until the same runtime-restart race is hit again.'], 'Identify and tear down only the confirmed-orphaned cgroups/namespaces (cross-checked against the container runtime\'s own state, not just kubectl) rather than restarting the whole node, which would also disrupt every healthy workload on it.', 'Track node-level allocatable-vs-actually-accounted resource drift as its own alert independent of Pod-level health, patch the container runtime to the version that fixes the underlying cleanup race, and periodically reconcile cgroup/namespace inventory against the container runtime\'s own record rather than trusting the Kubernetes API alone. See Volume 1, Chapter 5 for the namespace/cgroup mechanism this leak actually depends on.'),
];
